quests[78690] = { id = 78690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emotionale Stütze", sourceObjective = "Sprecht mit 10 Einwohnern von Velhans Geltung.", progress = "Es ist unglaublich wichtig, die Bürger von Velhans Geltung zu beruhigen, {name}, und ihnen zu versichern, dass schon alles gut werden wird. In diesen dunklen Zeiten ist Hoffnung das Allerwichtigste.", completion = "Wir sind zum Helfen gekommen, aber die Vergangenheit hat mich gelehrt, dass es manchmal viel wichtiger ist, den Leuten Hoffnung zu spenden und sie zu bestärken.\n\nWährend Ihr Euch mit den Einwohnern unterhalten habt, haben Taenar und ich über das weitere Vorgehen nachgedacht.\n\nWir dürfen die Leute nicht überfordern, müssen ihnen etwas Luft zum Atmen lassen, aber sie auch auf den bevorstehenden Kampf vorbereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[78691] = { id = 78691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Eine, der entkam", sourceObjective = "Rettet Maximilian an der Absturzstelle der Unbeugsamkeit.", completion = "Ich weiß, es klingt abgedroschen, {name}, aber ich kann Euch gar nicht genug dafür danken, dass Ihr Max sicher nach Hause gebracht habt.\n\nDurch all das habt Ihr mir auch gezeigt, dass ich an der Spitze sein muss, um den Weg für meine Leute zu ebnen. Ich habe gesehen, dass es schlimmere Folgen als den Tod gibt. \n\nIch kann die Fehler, die ich in der Vergangenheit gemacht habe, nicht ungeschehen machen, aber ich kann sicherstellen, dass ich das nicht wiederhole.", sourceObjectiveStatus = "unverified-source-field" }
quests[78692] = { id = 78692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lehrt einen hungrigen Mann das Fischen...", sourceObjective = "Verteilt 8 Speere an die Einwohner von Velhans Geltung.", progress = "Habt Ihr die Speere schon verteilt? Die Leute brauchen sie, um sich daran zu erinnern, zu was sie fähig sind.", completion = "Ich denke, jetzt werden sie sich ganz anders verhalten, jetzt, wo sie bewaffnet sind.{name}.\n\nEs hat etwas, wenn man weiß, dass man auf sich selbst aufpassen kann, dass man seine eigenen Probleme bewältigen kann und niemanden braucht, der einen rettet.\n\nNatürlich werden wir Lampenanzünder immer da sein und helfen, aber es ist sehr wahrscheinlich, dass wir beim nächsten Mal nicht gebraucht werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[78693] = { id = 78693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speere gegen die Angst", sourceObjective = "Sammelt 8 Speere der Kobyss für die Leute von Velhans Geltung.", progress = "Machen die Kobyss Euch Ärger? Bald werden die Menschen von Velhans Geltung den Ärger zu ihnen bringen.", completion = "Gute Arbeit, {name}. Das ist genau, was wir brauchen, um die Kobyss nicht nur für einen Tag zurückzuschlagen, sondern um dafür zu sorgen, dass die Menschen von Velhans Geltung sich in Zukunft verteidigen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[78694] = { id = 78694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückeroberung von Velhans Geltung", sourceObjective = "Tötet 12 Krieger der Kobyss in der Nähe von Velhans Geltung.", completion = "Seit dem Tag, an dem die Kobyss meine getreuen Gefährten in die Nacht verschleppt haben, um sie zum Abendbrot zu verschlingen, hasse ich sie inbrünstig.\n\nDank Eurer Bemühungen heute wird hoffentlich kein Einwohner von Velhans Geltung dies je am eigenen Leib erfahren müssen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[78695] = { id = 78695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leuchtendes Licht", sourceObjective = "Stellt 8 Fackeln entlang der Grenze zu Velhans Geltung auf, bevor Ihr der Neuentfachung des Lichts im Dämmerturm beiwohnt.", completion = "Ihr habt meinen Sohn gerettet, {name}. Ihr habt das Rückgrat des Angriffs auf unser Zuhause gebrochen und uns Waffen gegeben, mit denen wir kämpfen können.\n\nIhr habt mir geholfen, der Anführer zu sein, dessen Rolle ich nur vorgespielt habe. Habt Dank.\n\nDie Lampenanzünder werden immer Verbündete in Velhans Geltung haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[78696] = { id = 78696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir gehen nicht nach Taelloch", description = "Dieser unruhige Maschinenflüsterer hatte hier irgendetwas vor. Aber was? Es sieht aus, als hätte ihm etwas großen Schaden zugefügt.\n\nWir sollten uns beeilen.\n\nWir müssen nach Taelloch und nach der Vorarbeiterin suchen. Könnt Ihr einen Weg in die Stadt sichern? Jemand könnte verletzt werden!", sourceObjective = "Säubert den Eingang nach Taelloch von den eindringenden Tieren.", completion = "Im Büro der Vorarbeiterin gibt es nicht viel zu sehen. Wenn wir Antworten wollen, müssen wir die Stadt durchsuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78697] = { id = 78697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geist einer Minenstadt", description = "Die Vorarbeiterin ist nicht hier. Offensichtlich. Aber die Hinweise deuten darauf hin, dass sie vor Kurzem hier war. Vielleicht ist sie also noch in der Nähe!\n\nWir sollten tiefer in die Stadt gehen und sehen, ob irgendjemand eine Ahnung hat, wo sie sein könnte.\n\nOder vielleicht kann uns jemand anderes die Antworten geben, die wir brauchen. Vielleicht finden wir es auch selbst heraus! Vielleicht war es irgendeine Art Angriff oder... Entschuldigung. Ich steigere mich zu sehr hinein. Machen wir uns an die Untersuchungen!", sourceObjective = "Nutzt die Fähigkeit 'Untersuchen', um Hinweise darauf zu finden, was in Taelloch passiert ist.", completion = "Gut... Damit haben wir vielleicht eine Frage beantwortet. Und Dutzende weitere aufgeworfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78700] = { id = 78700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kontrollierter Abriss", description = "Ich weiß, dass wir schon früher gegen die Skardyn gekämpft haben, aber das hier... ist schlimmer.\n\nIch wusste, dass die Skardyn die Irdenen in noch mehr Skardyn verwandeln, aber damit hatte ich nicht gerechnet... die Kristalle... die Stacheln... die aufgewühlte blaue Energie... dieser Geruch! Das ist ganz und gar nicht das, was ich erwartet hatte. \n\nWenn wir uns dorthin wagen müssen, werde ich unterwegs einige dieser Abscheulichkeiten ausschalten.", sourceObjective = "Tötet 18 Skardyn in Taelloch", progress = "Es gibt noch mehr zu tun. Wir können nicht zulassen, dass sich diese Verderbnis ausbreitet.", completion = "Vielleicht haben wir nur einige wenige Skardyn aus einem wesentlich größeren Schwarm getötet. Aber wir müssen ja irgendwo anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78701] = { id = 78701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wahrheit in Kreide", description = "Die Einwohner von Taelloch benutzen also Kreide und Schiefertafeln, um sich gegenseitig Nachrichten zu hinterlassen. So viele Hinweise! Aber was bedeutet das alles...\n\nIch erkenne ein Muster, und ich glaube, es weist auf die Minen hin. Wenn die Arbeiter nicht schon verloren sind, würde ich sie dort vermuten.\n\nUnd ich weiß, dass die Vorarbeiterin der Schlüssel ist. Das muss sie sein.", sourceObjective = "Sucht nach Nachrichten in der Taellochmine.", progress = "Hier gibt es noch mehr zu erfahren. Da bin ich sicher.", completion = "Ich glaube, ich weiß, wo wir als Nächstes hingehen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78703] = { id = 78703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschüttet in Stein", description = "Wir müssen in die Höhle gehen, die auf der letzten Tafel erwähnt wurde. Es gab keine Unterschrift, aber ich glaube, das ist die Handschrift der Vorarbeiterin... und wir haben überall sonst gesucht. Wir müssen dem nachgehen.", sourceObjective = "Untersucht die Höhle am Ende der Taellochmine.", progress = "Wir übersehen etwas... Da muss etwas in der Höhle sein!", completion = "Ich wusste es! Ich hatte recht! Hier ist etwas. Jemand hat versucht, etwas zu verstecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[78704] = { id = 78704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach der Vorarbeiterin", description = "Dagran hatte recht. Ich schätze, das sollte mich nicht mehr überraschen.\n\nAlles deutet darauf hin, dass etwas in dieser Höhle ist. Vielleicht versteckt sich die Vorarbeiterin hier. Vielleicht kann sie uns ein paar Antworten geben.\n\nWir haben es bis hier geschafft. Finden wir heraus, was da drin ist.", sourceObjective = "Findet die Vorarbeiterin.", progress = "Tiefer in der Höhle muss es Antworten geben.", completion = "Das war sie. Die Vorarbeiterin. Sie muss es sein. Nach all dem... war sie bereits fort.", sourceObjectiveStatus = "unverified-source-field" }
quests[78705] = { id = 78705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was sie sah", description = "Was ist das? Dieses Ding, das der Skardyn fallengelassen hat, bevor wir... bevor er starb.\n\nIch glaube, ich habe so etwas schon einmal gesehen.", sourceObjective = "Untersucht den Edelstein, den der Skardyn zurückgelassen hat.", progress = "Ich glaube, ich weiß, was das für ein Edelstein ist...", completion = "Oh. Das ist schlimm, nicht wahr?\n\nDie Vorarbeiterin entdeckte diese Verschwörung in der Halle des Erwachens.\n\nDanach reiste sie mit ihrem Erinnerungsedelstein zurück nach Taelloch.\n\nSie versuchte, die anderen zu warnen, aber sie wurde infiziert... und ihre Verwandlung verlief schnell. Sie schloss sich in dieser Höhle ein, aber ihre Verderbnis breitete sich weiter aus.\n\nUnd der Oberste Sprecher wusste, was passieren würde. Der Oberste Sprecher steckt hinter alledem!\n\nWir müssen Brinthe warnen. Wir müssen die Welt warnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78706] = { id = 78706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geheimnis des Obersten Sprechers", sourceObjective = "Kehrt zu Brinthe in Gundargaz zurück.", completion = "Danke, dass Ihr das Geheimnis um Taellochs Heimsuchung untersucht habt.\n\nWas habt Ihr herausgefunden?", sourceObjectiveStatus = "unverified-source-field" }
quests[78713] = { id = 78713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Krieg im Inneren", description = "Auf ganz Azeroth wird eine Vision wahrgenommen. Ein strahlender Gesang. Wir glauben, dass es eine Warnung ist, sind aber nicht sicher, wovor er uns warnt.\n\nTrefft mich in Silithus. Wir müssen Azeroths Sprecher dazu befragen, was diese Vision bedeutet.", sourceObjective = "Geht nach Silithus und sprecht mit Thrall über die Visionen, die sich über Azeroth verbreiten.", completion = "Es sind alle da. Gut. Finden wir heraus, was der strahlende Gesang uns zu sagen versucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[78714] = { id = 78714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein dürftiger Empfang", description = "Es gibt nicht zu leugnende Hinweise darauf, dass der strahlende Gesang eine Warnung von Azeroth selbst ist. Ein Hilferuf.\n\nDarum sind wir hier. Wenn diese Vision wirklich eine Nachricht von Azeroth ist, wird Magni wissen, was sie uns sagen soll.\n\nEr sollte in der Herzkammer sein. Gehen wir.", sourceObjective = "Geht in die Herzkammer und bittet Magni um Hilfe, den strahlenden Gesang zu verstehen.", completion = "Ich weiß, warum Ihr hier seid. Wegen der Visionen. Azeroths Stimme hallt in allen Landen wider. Ihr dachtet, ich wüsste, was sie uns sagen will. \n\nNun, da habt Ihr falsch gedacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[78715] = { id = 78715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azeroths Stimme", description = "Ich habe seit Jahren nicht mehr mit Azeroth gesprochen. Anfangs hatte ich einfach nicht das Bedürfnis. Dann spürte ich, wie ich mehr und mehr einen Groll gegen sie hegte. Weil sie mich... so zurückgelassen hatte. Und jetzt bin ich mir nicht sicher, ob ich überhaupt noch mit ihr sprechen kann.\n\nAber ich weiß, was auf dem Spiel steht. Ihr strahlender Gesang kündet von finsteren Dingen. Und wir müssen wissen, von welchen.\n\nZunächst müssen wir die Herzkammer vorbereiten. Könnt Ihr die Konsolen in der Nähe aktivieren?", sourceObjective = "Helft Magni, sein Ritual durchzuführen.", progress = "Ich verstehe Magnis Sorgen, aber wir haben keine Wahl. Die Zukunft unserer Welt steht auf dem Spiel. Wir müssen alles in unser Macht Stehende tun, um zu verstehen, wovor uns Azeroth zu warnen versucht.", completion = "Dies ist nie zuvor geschehen. Magni ist der Sprecher von Azeroth. Warum sollte ein Versuch, Zwiesprache mit ihr zu halten, zu einem Zusammenbruch führen?", sourceObjectiveStatus = "unverified-source-field" }
quests[78716] = { id = 78716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmerzhafte Lektionen", description = "Magni scheint vorerst stabil zu sein, doch er reagiert immer noch nicht. Wir müssen ihn schnell behandeln lassen. Ich öffne ein Portal nach Dalaran.\n\nFolgt uns, sobald Ihr könnt.", sourceObjective = "Nehmt das Portal nach Dalaran.", completion = "Ich bin nicht sicher, warum der Sprecher von Azeroth in so einen Zustand verfallen sollte, nachdem er versuchte... nun, mit Azeroth zu sprechen.\n\nWir können jetzt nur darauf warten, dass sich Magni erholt.", sourceObjectiveStatus = "unverified-source-field" }
quests[78717] = { id = 78717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine mysteriöse Warnung", description = "Nun, das war ein ganz besonderes Nickerchen. Ich hätte nicht erwartet, dass Azeroth so... laut ist. Für normale Ohren klingt es wie ein leises Rufen. Aber durch unsere Verbindung hört es sich an, als würde sie schreien. Und zwar direkt in meine Kristallohren.\n\nAber ich habe es gesehen. Khaz Algar, eine Insel der Irdenen, eingetaucht in Feuer und Rauch. Azeroth versucht, uns dorthin zu führen.\n\nDas ist es, was wir schützen müssen.", sourceObjective = "Beratet über die nächsten Schritte und sprecht dann mit Khadgar.", completion = "Der Rat hat sich entschieden. Wir reisen nach Khaz Algar.\n\nDalaran wird den Teleport ausführen, sobald wir bereit sind. Werdet Ihr uns bei den Vorbereitungen helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[78718] = { id = 78718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärken der Schutze", description = "Magnis Vision prophezeit, dass Khaz Algar möglicherweise... turbulente Zeiten bevorstehen. Und so ist es am besten, sicherzustellen, das Dalaran auf das Schlimmste vorbereitet ist.\n\nHier, nehmt diesen Stab. Er ist auf die Verteidigungsmagie Dalarans eingestimmt.\n\nSchwingt ihn in der Nähe von strategischen Teilen der Stadt, um unsere magischen Verteidigungen zu stärken.", sourceObjective = "Verstärkt Dalarans Verteidigung.", progress = "Es wird uns sehr schwerfallen, Khaz Algar zu retten, wenn unsere eigene Verteidigung nicht stark genug ist, einem Angriff standzuhalten.", completion = "Gut gemacht, Champion.\n\nHoffen wir nur, dass es ausreicht. Ich möchte nicht, dass unserer Stadt etwas zustößt, nun, da die Welt uns am meisten braucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[78719] = { id = 78719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bürger von Dalaran", description = "Unsere Bürger müssen auf Dalarans Abreise vorbereitet werden. Könnt Ihr Euch in der Stadt umsehen und fragen, ob jemand Hilfe benötigt?\n\nIch möchte auch, dass Ihr mit Brann und Erzmagier Drenden sprecht. Die beiden haben Anliegen, derer wir uns annehmen müssen, bevor wir nach Khaz Algar aufbrechen.", sourceObjective = "Helft den Bürger von Dalaran, sich auf die Teleportation vorzubereiten.", progress = "Dalaran steht immer bereit, die Welt zu verteidigen, aber das bedeutet nicht, dass wir das nach Lust und Laune tun können. Vorbereitungen sind der Schlüssel zu einer problemlosen Translokation.", completion = "Danke für Eure Hilfe. Es ist wichtig, dass die Bürger von Dalaran auf alles vorbereitet sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[78721] = { id = 78721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Team", description = "Wenn wir neues Land in Khaz Algar erkunden wollen, dann werden wir die Hilfe der Forscherliga benötigen. Aber sie wird nicht alleine sein auf diesem Abenteuer. Die Liga schließt sich erneut mit der Archäologischen Akademie zusammen, genau wie auf den Dracheninseln.\n\nDiesmal nennen sie sich die Algariexpedition.\n\nIch mache mir nur ein wenig Sorgen, ob sie immer noch miteinander klarkommen. Erkundungsreisen können Leute genauso schnell auseinandertreiben, wie sie sie aneinander binden können. Könntet Ihr bei der Truppe vorbeischauen?", sourceObjective = "Seht nach der Algariexpedition.", progress = "Kommen ein Mitglied der Liga und eines der Expedition in eine Taverne... Nein, mir fällt nichts ein.", completion = "Sie verstehen sich? Na, da brat mir doch einer 'ne Ziege. Oh, nichts gegen Dagran.\n\nAber das macht meine Aufgabe auf jeden Fall einfacher. Trotzdem danke, dass Ihr bei ihnen vorbeigeschaut habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[78722] = { id = 78722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Khaz Algar!", description = "Wenn wir aus dem schließen, was Magni gesehen hat, dann ist Khaz Algar nicht das sicherste Reiseziel. Wir verlassen uns auf Euch, sollte ein Kampf ausbrechen.\n\nLasst mich wissen, wenn Ihr bereit seid, aufzubrechen.", sourceObjective = "Sagt Khadgar, dass Ihr bereit zur Abreise seid.", completion = "Sie war Erzmagier Drenden. Die ganze Zeit hat Xal'atath zugeschaut und Pläne geschmiedet, direkt unter meinen Augen. Wie konnte ich nur so blind sein?\n\nUnd jetzt fällt sie in Dalaran mit einer Armee aus Nerubern ein. \n\nXal'atath hat das geplant. Sie hat all das geplant. Sie wollte, dass wir nach Khaz Algar kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78724] = { id = 78724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Selbstliebe auf die eigene Art", description = "Wenn Ihr Euch für solch eine Herausforderung interessiert, habe ich eine Idee.\n\nIch habe einen prahlerischen Champion auf dem Weg nach Goldhain gesehen. Ihr könntet ihn zu einem Duell herausfordern.\n\nDas würde Eurem Wunsch gerecht werden, und Ihr könntet ihm eine wertvolle Lektion in Demut erteilen.", sourceObjective = "Besiegt Matley Graston in einem Duell in der Nähe von Goldhain.", progress = "Wie läuft Eure Herausforderung?", completion = "Täglich verrichtet Ihr für andere große Taten.\n\nHeute habt Ihr etwas Großes für Euch getan. Und das ist beste Geschenk von allen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78726] = { id = 78726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Selbstliebe auf die eigene Art", description = "Ein voller Bauch ist ein glücklicher Bauch!\n\nHier auf der Gala gibt es jede Menge köstliche Speisen und Getränke. Kauft Euch doch etwas Schönes, was meint Ihr?", sourceObjective = "Verzehrt Pakete mit Köstlichkeiten von Händlern auf der Gala der Geschenke.", progress = "Habt Ihr genügend leckere Speisen vertilgt? Ich für meinen Teil mag Obst sehr gerne.", completion = "Täglich verrichtet Ihr für andere große Taten.\n\nHeute habt Ihr etwas Großes für Euch getan. Und das ist beste Geschenk von allen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78727] = { id = 78727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Selbstliebe auf die eigene Art", description = "Für die Dauer der Gala habe ich mich im Gasthaus \"Zur Höhle des Löwen\" in Goldhain einquartiert.\n\nEs soll dort noch freie Betten in der oberen Etage geben. Seht doch einmal nach, ob Ihr dort ein wenig schlafen könnt.\n\nIch glaube, ich werde mich auch etwas ausruhen... gleich... hier...", sourceObjective = "Macht ein Nickerchen im oberen Gästezimmer im Gasthaus \"Zur Höhle des Löwen\".", progress = "<Ying schnarcht sanft.>", completion = "Hä? Oh! Willkommen zurück, habt Ihr Euch schön ausgeruht?\n\nTäglich verrichtet Ihr für andere große Taten.\n\nHeute habt Ihr etwas Großes für Euch getan. Und das ist beste Geschenk von allen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78729] = { id = 78729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stinker großziehen", description = "Hinter den von uns gefundenen Hinweisen steckt eine hässliche Geschichte, {name}.\n\nDie Karte zeigt, dass die Chemiemanufaktur Krone über eine schwer bewachte Operationsbasis im Silberwald verfügt. Und aus dieser Notiz und der Formel geht hervor, dass sie weiß, wie man etwas berauschend Toxisches zubereitet.\n\nIch kenne jemanden, der uns... handgemachte Produkte... zur Bekämpfung von Krone besorgen kann. Ich unterhalte mich mit dieser Person, und wir treffen uns dann vor der Burg Schattenfang.", sourceObjective = "Trefft Euch mit Inspektor Schnappbolz am Eingang der Burg Schattenfang im Silberwald.", completion = "Da seid Ihr ja, genau rechtzeitig.\n\nIch habe einen Plan für den Umgang mit dieser chemischen Konspiration.", sourceObjectiveStatus = "unverified-source-field" }
quests[78738] = { id = 78738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abwesender Sprecher", sourceObjective = "Trefft Sprecherin Brinthe in den Erdwerken.", completion = "Der Oberste Sprecher und seine Anhänger werden für ihre Verbrechen bezahlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78739] = { id = 78739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgrabung: Der Fund im Turm" }
quests[78741] = { id = 78741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mitfühlende Sprecher", description = "Ich muss den Obersten Sprecher daran hindern, noch mehr Skardyn zu erschaffen.\n\nDas Protokoll der Maschinenflüsterer schreibt vor, dass einer der Vorarbeiter dieses Bereichs einen Schlüssel für die Halle des Erwachens haben sollte. Kommt mit, dann spüren wir ihn auf!", sourceObjective = "Sucht nach Vorarbeitern der Maschinenflüsterer in den Erdwerken mit Sprecherin Brinthe.", completion = "Das sollte uns Zugang zur Halle des Erwachens verschaffen...", sourceObjectiveStatus = "unverified-source-field" }
quests[78742] = { id = 78742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf in den Erdwerken", sourceObjective = "Besiegt gegnerische Maschinenflüsterer, Konstrukte und helft verängstigten Arbeitern in den Erdwerken!", completion = "Ihr habt es geschafft, einige der ergebensten Anhänger des Obersten Sprechers zu vertreiben... und Ihr habt ein paar Köpfe eingeschlagen.\n\nDas ist ein guter Anfang. Aber es sind so viele... zu viele...", sourceObjectiveStatus = "unverified-source-field" }
quests[78743] = { id = 78743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor meinem Abschied", description = "Ich spüre, wie meine Energiereserven schwinden.\n\nBald werde ich meinen Pflichten nicht mehr nachkommen können. Deshalb ist Urtago bei mir, um sie zu übernehmen.\n\nBevor meine Systeme stillstehen, muss ich sicherstellen, dass Trauerhöhe frei von Kobolden ist. Sie haben die Gedächtnisstätte überrannt, um die ich mich kümmere, und plündern die Schreine der Freien und ihre Gebeine.\n\nVielleicht ist es gut, dass Ihr hier seid. Ihr habt die Kraft, uns zu helfen.\n\nBitte helft Urtago, den Ort von den Kobolden zu befreien.", sourceObjective = "Trefft Urtago an der Gedächtnisstätte Trauerhöhe.", completion = "Korgran bezeichnet sich immer als der Verwalter, doch schon seit einer Weile bin ich es, die sich um die Trauerhöhe kümmert.\n\nEs stört mich nicht. Korgran ist sehr gütig.\n\nAber die Lage hier ist mir entglitten. Uns steht ein hartes Stück Arbeit bevor.", sourceObjectiveStatus = "unverified-source-field" }
quests[78744] = { id = 78744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu Ehren ihres Andenkens", description = "Nehmt diese Gaben und platziert sie bei den früheren Verwaltern. Jede Gabe ist ein Zeichen, mit dem wir ihr Andenken ehren.\n\nIch würde auch gern die Außenanlagen etwas auf Vordermann bringen, damit die Stätte nicht völlig verwahrlost. Leider wird es Wochen dauern, alles in Ordnung zu bringen, was die Kobolde an der Gedenkstätte angestellt haben.\n\nBitte tut, was Ihr könnt, um mit den Plagegeistern fertigzuwerden. Es wäre unklug, die Gaben unbewacht zulassen, während sich die Kobolde hier noch herumtreiben.", sourceObjective = "Beseitigt die Koboldplage und legt Gaben nahe den deaktivierten früheren Verwaltern ab.", progress = "Wir dürfen nicht zulassen, dass die Kobolde Trauerhöhe entweihen.\n\nDie Freien, die hier ruhen, sind hier, weil sie nicht gestört oder bewegt werden wollen. Auch wenn sie nicht wiederbelebt werden wollen, ist es eine Schande für die Kultur der Irdenen, ihnen ihre Rüstungen und Besitztümer zu nehmen.\n\n Wir müssen etwas tun.", completion = "Ich kann kaum fassen, wie viel Schaden die Kobolde an der Stätte angerichtet haben. So viele deaktivierte Irdene wurden geschändet!\n\nIch weiß, dass ich noch nicht die leitende Verwalterin bin, doch ich übernehme die volle Verantwortung dafür. Ich hätte vor langer Zeit darum bitten müssen, die Aufgabe als Verwalterin offiziell zu übernehmen, als Korgran die ersten Anzeichen für Gedächtnisüberschreibung und Stasisblockade zeigte.", sourceObjectiveStatus = "unverified-source-field" }
quests[78745] = { id = 78745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Du nicht nehmen Beute!", description = "Wie es scheint, haben die Kobolde Edelsteine und andere... Körperteile von diesen deaktivierten Irdenen geraubt.\n\nAbscheulich.\n\nFindet heraus, wo die Kobolde ihre Beute verwahren und bringt sie zurück, damit ich sie später wieder an ihrem rechten Ort platzieren kann.\n\nDieser Vandalismus darf nicht ungesühnt bleiben!", sourceObjective = "Erlangt das Irdeneneigentum aus den Beutehäufen zurück.", progress = "Konntet Ihr die Beute finden?", completion = "Vielen Dank für Euren Einsatz.\n\n<Urtago nickt sich bestätigend zu, während sie die Gegenstände in Augenschein nimmt.>\n\nIch bin sehr erleichtert, aber es bleibt noch viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[78746] = { id = 78746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesetze gelten für alle", description = "Die Entweihung einer Gedenkstätte ist eins der größten Tabus in unserer Irdenen Gesellschaft. Diese Stätte ist ein Fenster zu unserer Vergangenheit, zu unseren Erinnerungen. Sie ist ein Ort der Selbstreflexion, an dem wir uns mit denen austauschen können, die nicht mehr hier sind.\n\nDennoch befallen viele dieser Kobolde Trauerhöhe. Für ihre Verbrechen haben die Kobolde die härteste Strafe verdient. Sie müssen noch weiter dezimiert werden.", sourceObjective = "Tötet Koboldeindringlinge in Trauerhöhe.", progress = "So viele dieser Unholde hausen noch immer auf der Trauerhöhe.", completion = "Ich wurde weder als Irdene des Schwerts geschaffen, noch als jemand, der nach Gewalt ruft. Das ist die Domäne der Sturmreiter.\n\nDoch was diese Kobolde getan haben, wird nicht nur von uns Freien geächtet, sondern von der gesamten Gesellschaft der Irdenen. Ich bin nicht stolz darauf, dass wir sie töten mussten, doch um sie aufzuhalten, war jedes Mittel rechtens.", sourceObjectiveStatus = "unverified-source-field" }
quests[78747] = { id = 78747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Licht am Ende des Tunnels", description = "Jetzt, da wir ihnen einen mächtigen Schlag versetzt haben, wird es Zeit, ihre Tunnel zu beseitigen, damit sie nicht zurückkommen können.\n\nErinnert Ihr Euch an das Zeug, nach dem Korgran sich erkundigte? Explosive Stangen - nach seinem Rezept. Ich habe genug davon mitgebracht, um einen ganzen Berg zum Beben zu bringen! Mehr als genug für diese Kobolde.\n\nHelft mir, diesen Kobolden zu zeigen, dass wir bereit sind zu kämpfen, um zu verteidigen, was uns gehört. Nur so kommen sie nie wieder zurück!", sourceObjective = "Sprengt die Tunnel der Kobolde mit den explosiven Stangen.", completion = "Haha! Hab ich's nicht gesagt? Ich konnte die Schockwellen bis hierhin spüren!", sourceObjectiveStatus = "unverified-source-field" }
quests[78748] = { id = 78748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Docht kürzer", description = "So wie ich die Kobolde kenne, haben sie mehrere \"Werkmeister\" oder Anführer, die diesen Beutezug leiten.\n\nFindet und erledigt diese sogenannten Werkmeister. Daraufhin wird der Rest der Meute im Chaos versinken, vergessen, warum sie überhaupt hier sind und uns hoffentlich in Frieden lassen.", sourceObjective = "Findet und tötet die Koboldwerkmeister.", completion = "Die planenden Köpfe hinter dieser Operation auszuschalten, verschafft uns nur mehr Zeit, wenn und falls die Kobolde beschließen, es wieder zu versuchen.\n\nLeider ist da noch ein Koboldhirn, das wir übersehen haben. Bis jetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[78749] = { id = 78749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer ist Herr dieses feinen Etablissements?", description = "Während Ihr mit den Tunneln und den Werkmeistern beschäftigt wart, sah ich einen merkwürdigen Kobold in eine Höhle im Nordwesten gehen. Die Kobolde schienen ihm außergewöhnlichen Respekt entgegenzubringen, nannten ihn Großräuber Bokk und boten ihm das Essen an, das Ihr \"Käse\" nennt. Das lässt mich darauf schließen, dass er der wahre Drahtzieher ist.\n\nWenn dieser Kobold tatsächlich hinter dieser Operation steckt, sollten wir die Gelegenheit nutzen, ihn auszuschalten.\n\nIch treffe Euch bei der Höhle.", sourceObjective = "Tötet Großräuber Bokk.", completion = "Ich freue mich, Euch zu sehen, {name}.\n\nIch spüre, wie mein Inneres knirscht. Das ist ein Zeichen für Unruhe. Mit jedem Moment nähert sich Korgrans Deaktivierung, und dann obliegt die Sorge für diesen Ort allein mir.\n\nEs ist eine große Verantwortung. Aber ich glaube, ich bin dafür bereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[78754] = { id = 78754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Postweg verloren", description = "<Ihr findet ein kleines, aber schweres ledergebundenes Paket auf der Straße, an dem ein Etikett befestigt ist.>\n\nGundargaz Kurierexpress\n\nEXPRESS\n\nAN: \nErnterin Farnee\nDurgazhütte\n\nVORSICHTIG ÖFFNEN: Enthält instabile Elementarmineralien.", sourceObjective = "Bringt das verlorene Paket zu Ernterin Farnee an der Durgazhütte.", completion = "Rauch mir den Bienenstock... Ihr habt es gefunden! Ich kann immer noch nicht fassen, dass der Kurier mein Päckchen einfach verloren hat...\n\nWir haben darauf gewartet, um Schieferhufs Bein zu behandeln.\n\nGemischt mit Feuerhonig wird ihn das Zeug bald wieder gesund machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[78755] = { id = 78755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlammspiele", description = "Wisst Ihr noch, wie wir Schieferhuf mit diesem Ton und dem Feuerhonig geflickt haben? Lasst es uns noch mal machen, aber diesmal im großen Stil!\n\nDas Problem ist, uns ist der Ton ausgegangen. Aber zum Glück ist nach der jüngsten seismischen Aktivität eine ganze Lawine von Elementaren aus ihrer Starre erwacht und sorgt am östlichen Strand für Chaos!\n\nBringt mir nassen elementar-aufgeladenen Schlick, den wir als Heilsubstrat verwenden können.", sourceObjective = "Sammelt 20 Handvoll elementargeladenen Schlick", progress = "Wenn wir lebenden Sand und Wasser kombinieren, können wir einen elementaren Schlick herstellen, der die Heilwirkung des Untertons imitiert. Oder ihr zumindest nahekommt!\n\nIst Elementarfusion nicht faszinierend?", completion = "Spürt Ihr die Energie des Schlicks zwischen Euren Fingern, {name}? Wie er voller Aufladung summt?\n\nIst das nicht aufregend? Verleiht es Euch nicht das Gefühl, eins mit der Erde und den Bergen zu sein?", sourceObjectiveStatus = "unverified-source-field" }
quests[78756] = { id = 78756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Massenhaft Feuerhonig", description = "Wenn Harmot diesen schlafenden Felsen heilen und aus meinem Teich holen will, habe ich sicher keine Einwände.\n\nLeider sind meine letzten Vorräte an Feuerhonig draufgegangen, als wir Schieferhufs Wunde versorgt haben. Und mit all diesen Elementaren, die Amok laufen, bin ich noch nicht dazu gekommen, neuen Honig aus dem Aschenholtz zu ernten.\n\nMacht Euch zum Rande des Holtzes auf und bringt uns Honig. Wir brauchen eine Menge.", sourceObjective = "Findet eine Menge Feuerhonig.", progress = "Seid vorsichtig in meinem Wald. Wir brauchen die Glutbienen, weil sie den Honig für unseren Met produzieren, aber sie sind nicht ungefährlich.", completion = "Ihr habt ihn WO gefunden?! Ein lebendiger Honig wa...?\n\n<Farnee spricht den Satz nicht zu Ende und senkt ihre Stimme.>\n\nBehalten wir die Neuigkeiten von lebendigem Feuerhonig lieber für uns. Harmot könnte abgelenkt werden und sich in Gefahr begeben, wenn wir es ihm sagen...", sourceObjectiveStatus = "unverified-source-field" }
quests[78757] = { id = 78757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honig und Ton und das Leid schwindet schon", description = "Ramolithen! Sind sie nicht eindrucksvoll? Sie gehören zu den schönsten Elementarbestien der Insel.\n\nLeider sind sie nicht immun gegen Verletzungen. Der arme Schieferhuf wurde von erweckten Elementaren in Farnees Teich verwundet.\n\nZum Glück haben wir aber alles, was wir brauchen, um ihn zu versorgen.\n\nWir müssen bloß diesen Ton mit etwas Feuerhonig vermischen und Schieferhufs Sprunggelenk damit einreiben!\n\nBereit?", sourceObjective = "Helft Harmot, Schieferhufs Salbe herzustellen.", progress = "Ähnlich wie bei uns Irdenen ist es keine leichte Aufgabe, etwas aus Fels und Stein zu heilen.\n\nAber die einzigartigen Eigenschaften des Tons, den Ihr mitgebracht habt, in Kombination mit den verschmelzenden Eigenschaften des Honigs ergeben ein hervorragendes Heilmittel!", completion = "Ihr seid ein Naturtalent, was die Elemente angeht. Habt Ihr mal drüber nachgedacht, so was beruflich zu machen?\n\nAber sagt mal, Ihr scheint ja keine Scheu zu haben, Euch schmutzig zu machen. Warum helft Ihr uns nicht bei Farnees Problem?", sourceObjectiveStatus = "unverified-source-field" }
quests[78758] = { id = 78758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Impuls in der Erde", description = "Bevor wir uns aufmachen und einen schlummernden Bergriesen aufwecken, sollten wir vermutlich zuerst in Erfahrung bringen, wie tief er schläft.\n\nAber wenn er nicht mal wachgeworden ist, als die Neruber sich hochgegraben haben, wüsste ich nicht, was ihn wecken könnte.\n\nNehmt diese Erdsplitter und platziert sie an den Wasserfällen und Hügeln um den Teich.\n\nSobald wir sie aufgestellt haben, kann ich die Gesundheit des Riesen analysieren.", sourceObjective = "Platziert 4 Bebensteine um den Teich.", progress = "Sobald Ihr die Splitter aufgestellt habt, platziere ich hier den letzten, damit ich eine gute Diagnose stellen kann.", completion = "Der Bergriese hat einen schwachen Herzschlag.\n\nDer Arme wurde vermutlich in seinem Schlummer gestört, als sich all die Elementare über den Fällen gelöst haben.\n\nAber er hat Glück, dass wir beide Experten in der Heilung von Elementaren und Elementar-verwandten Lebensformen sind, stimmt's?\n\nWenn die Salbe bei Irdenen und Gesteinswiddern hilft, sollte sie auch bei Bergriesen funktionieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[78759] = { id = 78759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfach riesig gegen Leiden", description = "Beim Kernweg, dieses Zeug hat echt Wumms!\n\nDie Kombination von heilendem Schlick mit den schmelzenden Verbundeigenschaften des Feuerhonigs ergibt eine Salbe, die einen ganzen Berg erwecken könnte!\n\nUnd genau das werdet Ihr tun. Bringt die Mixtur zu unserem verwundeten Freund in Farnees Teich und tragt sie ihm auf!\n\nDas sollte reichen, um ihn aufzuwecken und seine Leiden zu lindern.\n\nHoffe ich zumindest.", sourceObjective = "Tragt für Harmot die Elementarsalbe auf den Bergriesen auf.", progress = "Damit wacht der Riese entweder erholt und geheilt auf oder...\n\nAch, reden wir nicht über die Alternativen. Vertraut einfach auf das Verfahren!", completion = "Tja, sieh mal einer an!\n\nDa schlummert er erst Tausende Jahre am Fuße eines Wasserfalls und dann wacht er auf, ohne auch nur zu brüllen oder mit den Füßen aufzustampfen.\n\nHah! Und Farnee hat sich noch Sorgen gemacht!\n\nIhr habt mit dieser Salbe ganze Arbeit geleistet, {name}. Farnee und ich sind Euch zu großem Dank verpflichtet.\n\nUnser neuer Freund sieht auch ziemlich dankbar aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[78760] = { id = 78760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkeleisen von oben", description = "Wir haben unser Bestes gegeben, um die Anhänger des Obersten Sprechers aufzuhalten. Wir haben verhindert, dass sie alles zerstören oder plündern, um es in die Halle des Erwachens mitzunehmen.\n\nJetzt müssen wir uns nur noch um den Anführer ihrer Truppen kümmern, bevor sie ihren Widerstand koordinieren können.\n\nSeid Ihr dazu bereit, {name}?", sourceObjective = "Besiegt Vorsteher Varric und seine Truppen in den Erdwerken.", completion = "Die Schallenden Tiefen sollten fürs Erste sicher sein... Aber der Oberste Sprecher...\n\nWir müssen Sprecherin Brinthe in die Halle des Erwachens folgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78761] = { id = 78761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Maschine", description = "Keine Zeit zum Durchatmen! Der Oberste Sprecher flieht zur heiligsten Maschine der Irdenen. Wir müssen ihm folgen.\n\nDenkt daran, wir tun das für die Irdenen! Für die Gerechtigkeit! Für alle Brüder und Schwestern und Kameraden, die dem Hochmut des Obersten Sprechers zum Opfer gefallen sind!", sourceObjective = "Stellt den Obersten Sprecher in der Halle des Erwachens.", completion = "Er ist fort? Er ist wirklich fort?\n\nSoweit es mich angeht, hat er damit seine Autorität aufgegeben. Ich weiß nicht, wohin er geflohen ist, und es interessiert mich auch nicht. Jetzt, da die Erweckungsmaschine wieder funktionsfähig ist, können wir die Dinge endlich geraderücken.", sourceObjectiveStatus = "unverified-source-field" }
quests[78762] = { id = 78762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer erster Fund", description = "Wir haben einen Fund! Sieht aus, als könnte das mein altes Lehrbuch sein. Hah!\n\nGut, Eure Aufgabe ist jetzt, all diesen Schmutz zu entfernen, aber Ihr müsst vorsichtig sein. Die Artefakte, mit denen wir es zu tun haben, sind sehr zerbrechlich, und das Einzige, was schlimmer ist, als sie im Boden zu lassen, ist, sie beim Rausholen kaputt zu machen.\n\nWenn Ihr Euren Elementar ermächtigt, ist das nur die halbe Miete. Ihr müsst Eure Umgebung einsetzen, um alles im Gleichgewicht zu halten und eine sichere Ausgrabung zu gewährleisten.", sourceObjective = "Übt Ausgrabungen mit dem veralteten Geologiebuch.", completion = "Das hätten wir! Euer erstes Artefakt... sozusagen.\n\nDas Zeug, das wir im Feld finden, ist normalerweise aufregender. Aber immerhin könnt Ihr das als Souvenir behalten!", sourceObjectiveStatus = "unverified-source-field" }
quests[78763] = { id = 78763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonflight (70) E" }
quests[78789] = { id = 78789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flugsteine" }
quests[78820] = { id = 78820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Technosehen: Die Geheimnisse von Igiras Wacht" }
quests[78821] = { id = 78821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erblühende Traumsaat", description = "Im Smaragdgrünen Traum geht es um die Harmonie und das Gleichgewicht in der Natur. Damit Amirdrassil erblühen kann, benötigen wir eine große Vielfalt an Pflanzen, die zusammen mit dem Weltenbaum wachsen können. Pflanzt die Samenkörner ein, wo Ihr fruchtbare Erde findet.", sourceObjective = "Pflanzt Traumsaat im Smaragdgrünen Traum.", progress = "Wie geht es mit dem Einpflanzen voran?", completion = "Habt Dank! All diese kleinen Taten machen es möglich, dass der Smaragdgrüne Traum erblüht und Amirdrassil genährt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[78827] = { id = 78827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nehmt Kerze!", description = "Ksk, ksk! Ihr da! Ja, Ihr!\n\n<Ihr hört die Geräusche einer Rempelei hinter dem Schacht und eine neue, noch kratzigere Stimme ertönt.>\n\nWir, ähm, ich habe eine Aufgabe für Euch. Ihr seht schlau aus. Seht schnell aus. Schnelle Hände, genau wie wir... ich! Schnelle Hände genau wie ich.\n\nBringt uns, mir, bringt mir Kerzen! Ja!\n\nNicht fragen, bringt nur Kerzen.\n\nWir sind, ähm, ich bin ein Profi, ja. Profis stellen keine Fragen.\n\nHolen nur Kerzen.", sourceObjective = "Stehlt Kerzen für den verdächtigen Schacht im Gasthaus von Gundargaz.", progress = "Ihr habt Kerzen?", completion = "<Überschwänglicher Gesang ist hinter dem Schacht zu hören.>\n\nKerze! Kerze! Kerze!\n\nStill! Pssst! Die Steinernen dürfen nichts hören...", sourceObjectiveStatus = "unverified-source-field" }
quests[78837] = { id = 78837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pomp und schlimme Umstände", description = "Ich beobachte viele berechtigte Bedenken. Wir müssen etwas wegen der Neruber unternehmen... auch wenn der Oberste Sprecher es nicht tut. Wenn er nichts unternimmt, werde ich es tun.\n\nDer Oberste Sprecher hat mich zur Oberfläche geschickt, weil ich nicht \"vernünftig\" war. Ich glaube, wir sollten eine Chance bekommen... \"vernünftig\" mit ihm zu sprechen. Wir müssen nach Gundargaz.", sourceObjective = "Trefft Sprecherin Brinthe in Gundargaz.", completion = "So viel zur Vernunft.\n\nDie Schallenden Tiefen haben viele Probleme, und der Oberste Sprecher ist eindeutig abgelenkt. Er klingt wie besessen!\n\n{name}, wenn Ihr und Eure Begleiter uns helfen könnt, einige unserer Herausforderungen hier zu bewältigen, dann kann ich vielleicht die Maschinenflüsterer überreden, Euch gegen die Neruber beizustehen. Dieses Problem betrifft uns alle.", sourceObjectiveStatus = "unverified-source-field" }
quests[78838] = { id = 78838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rädchen im Getriebe", description = "Gundargaz ist meine Heimat. Oder sie war es, bevor der Oberste Sprecher der Meinung war, er müsse mich an die Oberfläche versetzen. Ich habe meine Heimat vermisst, aber... sie hat sich verändert.\n\nDie Zahlen der Maschinenflüsterer schrumpfen stetig. Das ist ein Rennen gegen die Zeit.\n\nNeuerdings sind wir der Aufgaben, die uns zugewiesen wurden, besonders überdrüssig. Doch es nützt nichts, wir müssen unsere Last tragen.\n\nLasst mich Euch trotzdem herumführen. Es gibt einige Irdenen, die ich Euch gerne vorstellen würde.", sourceObjective = "Begleitet Brinthe, während sie mit Irdenen in Gundargaz spricht.", completion = "Die Probleme nehmen zu und unsere Reihen lichten sich.\n\nDer Oberste Sprecher ist abgelenkt, Kobolde greifen an, Lieferungen aus Taelloch verschwinden und die Irdenen kehren nicht von ihren Schichten zurück.\n\nWo fangen wir bloß an? Wir haben einiges zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[78839] = { id = 78839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Koboldkonzentration", description = "Der erste Schritt, um unsere Verluste zu begrenzen und die Minen zurückzuerobern, ist klar, wenn auch unangenehm. Ohne seine Handlanger wird der Kerzenkönig eine geringere Bedrohung für Gundargaz darstellen.\n\nVersucht, den Schwarm zu dezimieren, {name}, bevor die Feindseligkeiten weiter eskalieren.", sourceObjective = "Tötet die eindringenden Kobolde in den Verlorenen Minen.", progress = "Das hätte nie geschehen dürfen.", completion = "Grausige Arbeit, aber notwendig.", sourceObjectiveStatus = "unverified-source-field" }
quests[78860] = { id = 78860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Kerzen!", description = "Ich, ähm, wir... nein, nein, ich! Ich habe ein neues Angebot für Euch, oh <Schattenhaftiger/Schattenhaftige>!\n\nMehr Kerzen!\n\nDafür bekommt ihr... ähm...\n\n<Wildes Scharren enthüllt eine neue Stimme.>\n\nIhr holt mehr Kerzen! Dann gebt Ihr uns! Mir!\n\nKerzen! Kerzen! Kerzen!\n\n<Der aufgeregt geflüsterte Gesang setzt sich noch eine Weile fort.>", sourceObjective = "Stehlt mehr Kerzen für den verdächtigen Schacht im Gasthaus von Gundargaz.", completion = "Ksk! Ihr habt es geschafft!\n\nMehr Kerzen...\n\n...Kerzen ohne Ende.\n\n<Der Schacht verströmt ein spürbares Gefühl der Ehrfurcht.>", sourceObjectiveStatus = "unverified-source-field" }
quests[78861] = { id = 78861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterstützt das Abkommen" }
quests[78863] = { id = 78863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Platz unter den Ästen", description = "Dank Euch und all den Sterblichen, die den Smaragdgrünen Traum verteidigt haben, wächst nun ein neuer Weltenbaum auf den Dracheninseln.\n\nAmirdrassils Äste werden eine Zuflucht voller Frieden und Ruhe sein und ein Ort der Erholung für die Seelen der Kaldorei, die ihr Leben in Teldrassil verloren.\n\nTyrande Wisperwind und Shandris Mondfeder sind gerade am Baum. Sie möchten mit Euch sprechen.", sourceObjective = "Trefft Tyrande und Shandris in Amirdrassil.", completion = "Willkommen in Bel'ameth, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[78864] = { id = 78864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr", sourceObjective = "Sprecht mit Shandris Mondfeder.", completion = "Mein Vater ist endlich zu uns zurückgekehrt, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[78865] = { id = 78865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschwister bis zum Ende", description = "Vor einer Weile erhielt Vyranoth eine unerwartete Einladung... von Iridikron.\n\nEs dürfte Euch interessieren, was er zu sagen hatte.", sourceObjective = "Sprecht mit Vyranoth, um mehr über ihr Treffen mit Iridikron zu erfahren.", completion = "Ich weiß nicht, was Iridikron als Nächstes vorhat. Aber ich kann ihn nicht länger \"Bruder\" nennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78866] = { id = 78866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superblüte: Schritt 2" }
