quests[78869] = { id = 78869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superblüte: Schritt 6" }
quests[78870] = { id = 78870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superblüte: Schritt 7" }
quests[78871] = { id = 78871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superblüte: Schritt 8" }
quests[78874] = { id = 78874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschworene Hilfe", description = "Falls Ihr auf der Suche nach Essen seid, weichem Essen, haben wir leider nichts mehr. Im Moment gibt es hier nur Steine und Juwelen.\n\nDas wird langsam zu einem Problem.\n\nSagt mal... Könntet Ihr vielleicht etwas dagegen tun? Könntet Ihr Verpflegung für das fleischliche Volk auftreiben?", sourceObjective = "Beschwört Essen für Gastwirt Brax im Gasthaus von Gundargaz.", progress = "Ihr wollt nicht mal ein Häppchen Kobalt probieren?", completion = "Schlagt mich mit dem Hammer und nennt mich Amboss! Das ist eine Menge Essen!", sourceObjectiveStatus = "unverified-source-field" }
quests[78875] = { id = 78875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Untötbare", description = "Ich möcht wett'n, dass der Oger Mai'Zoth hinter all dem hier steckt. Er hätte vor langer Zeit sterb'n soll'n, aber seine Magien sind weiter stark.\n\nEr wird das Altarmittelstück als Leitung nutz'n, um Lukous Macht abzugreif'n.\n\nSchnappt Euch das Mittelstück und beweist ihm, dass er ohne 'nen Loa als Geisel gar nich' so untötbar ist.", sourceObjective = "Holt Euch das Altarmittelstück von Mai'Zoth.", progress = "Habt Ihr bewies'n, dass auch Mai'Zoth 'n Ende find'n kann?", completion = "Das Mittelstück is' entscheidend. Es ist genutzt word'n, um Lukou direkt anzuzapf'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[78876] = { id = 78876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein glühendes Andenken", description = "<Eine ungewöhnlich hartnäckige Glut zieht Euren Blick auf sich. Sie glüht mit einer reinen, ursprünglichen Hitze.>\n\n<Vyranoth wäre daran interessiert.>", sourceObjective = "Bringt die ewig glühende Glut zu Vyranoth in Amirdrassil oder dem Zentrallager im Smaragdgrünen Traum.\n\nBereitgestellter Gegenstand:", completion = "Eine Glut der Urflamme, auf wundersame Weise unberührt von der Schattenflamme in jener schändlichen Höhle...\n\nIch danke Euch. Sie ist eine wärmende Erinnerung an den Bruder, den ich vor langer Zeit hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[78877] = { id = 78877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesegnet seien diese Heime", description = "Göttliche Gegenwart erkannt.\n\nSolange ich mich erinnern kann, bin ich jeden Tag die Wege gegangen und habe das Räucherwerk um unsere Häuser angezündet. Es hat meine Gelenke zu Staub zermahlen, aber es ist eine wichtige Aufgabe. \n\nEine heilige Aufgabe. \n\nDies sind dunkle Zeiten, in denen wir leben. Vielleicht könnt Ihr Eure eigenen Seligpreisungen zu unseren kleinen Ritualen hinzufügen?", sourceObjective = "Segnet das Räucherwerk in Gundargaz.", completion = "Wir alle sind Zahnräder in der Maschine. Wir drehen und drehen und drehen uns...\n\nDarin liegt eine eigene Schönheit.\n\nEine Ruhe.", sourceObjectiveStatus = "unverified-source-field" }
quests[78879] = { id = 78879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rufen der Schmiede", description = "Hmpf! Diese verflixte Schmiede pfeift aus dem letzten Loch. Wir würden sie reparieren, aber Steinmetz Itsak hat eine Schicht in Station Eisenhol übernommen, als der Kernweg einstürzte, und, nun ja...\n\nEs gibt niemanden mehr, der sie reparieren kann.\n\nWenn Euch einfällt, wie man sie wieder auf eine ordentliche Temperatur bringt, würde Gundargaz in Eurer Schuld stehen!", sourceObjective = "Findet einen Weg, die Schmiede vor Gundargaz anzuheizen.", progress = "Ich werde Itsak vermissen. Er machte nach einer Schicht immer die besten Steinbrocken-Steaks...", completion = "Oha! So etwas habe ich noch nie gesehen! Ihr habt einfach... Feuer in Eurem Hals?\n\nDas ist ein Trick, den ich gerne lernen würde!", sourceObjectiveStatus = "unverified-source-field" }
quests[78880] = { id = 78880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pokal der Östlichen Königreiche beginnt", description = "<Himmelsreiter/Himmelsreiterin>! Lord Andestrasz hat die Dracheninseln verlassen und ist zu Besuch in Sturmwind. Er sucht nach fähigen Himmelsreitern wie Euch zur Teilnahme an neuen Rennen!", sourceObjective = "Sucht Lord Andestrasz in Sturmwind auf.", completion = "Danke für den Besuch, Himmelsreiter!", sourceObjectiveStatus = "unverified-source-field" }
quests[78881] = { id = 78881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pokal der Östlichen Königreiche beginnt", description = "<Himmelsreiter/Himmelsreiterin>! Lord Andestrasz hat die Dracheninseln verlassen und ist zu Besuch in Orgrimmar. Er sucht nach fähigen Himmelsreitern wie Euch zur Teilnahme an neuen Rennen!", sourceObjective = "Sucht Lord Andestrasz in Orgrimmar auf.", completion = "Danke für den Besuch, Himmelsreiter!", sourceObjectiveStatus = "unverified-source-field" }
quests[78890] = { id = 78890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smaragdraserei" }
quests[78892] = { id = 78892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superblüte: Schritt 9" }
quests[78893] = { id = 78893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für einen Brocken Bronze", description = "Die Verkäufer von Pandaria wollen die Ausrüstung, die Ihr in dieser Zeitlinie findet, nicht haben.\n\nIhr könnt alle ungewünschte Ausrüstung in Bronze konvertieren, indem Ihr Euch die Magie des ewigen Drachenschwarms zunutze macht.\n\nSetzt die Fähigkeit 'Auflösungssand' ein und löst die Tunika des Auflösens auf.", sourceObjective = "Setzt die Fähigkeit 'Auflösungssand' ein, um Auflösungssand zu beschwören, und platziert dann die Tunika des Auflösens in dem Auflösungssand, um sie in Bronze zu verwandeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[78894] = { id = 78894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewiges Wachstum", sourceObjective = "Wenn Ihr mir genug Bronze bringt, werde ich Eure Ausrüstung ermächtigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78895] = { id = 78895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schatten über Gundargaz", description = "Ihr seht gefährlich aus.\n\n<Toki spuckt auf den Boden.>\n\nDas ist gut. Gefährlich können wir gebrauchen. Irgendetwas hat es auf Gundargaz abgesehen. \n\nEtwas Bösartiges. \n\nEtwas... Neuartiges. \n\nKurz bevor der Kernweg zusammenbrach, erhielt ich Berichte, dass mitten in der Schicht Arbeiter verschwunden waren. Das Einzige, was wir finden konnten, waren ein paar Felsbrocken.\n\nMeistens waren es Finger. \n\nWenn Ihr herausfinden könntet, was meine Stadt heimsucht, stünde ich in Eurer Schuld.", sourceObjective = "Findet, was auch immer die Irdenen in Gundargaz jagt.", progress = "Das Leben war nicht immer so aufregend.", completion = "Ein Dämon? Aus den Ruinen einer abgestürzten fliegenden magischen Stadt entkommen?\n\nWenn Ihr das sagt...\n\nIch bin nur froh, dass das ausgestanden ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[78897] = { id = 78897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schädlingsbekämpfung", description = "Dieser Ort ist von Höhlenbohrern verseucht. Sie stellen eine Gefahr für die großen Wurzeln dar, die sich durch dieses Gebiet ziehen.\n\nJa, der Baum nährt viele Lebewesen, aber das hier ist mehr als eine kleine Gruppe von Käfern, die ein Blatt anknabbern. Das hier ist eine Seuche. Sie müssen für das Gesamtwohl dezimiert werden.\n\nMein Eid verbietet mir, meine Hand zu erheben und hier einzugreifen. Aber... Ihr habt einen solchen Eid nicht abgelegt. Werdet Ihr tun, was getan werden muss?", sourceObjective = "Tötet 10 Würmer der Wurmlande.", completion = "Ihr habt meinen Dank, Fremdling.", sourceObjectiveStatus = "unverified-source-field" }
quests[78898] = { id = 78898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intention gegen Instinkt", description = "Höhlenbohrer sind gewöhnlicherweise keine sozialen Kreaturen. Dass sich so viele von ihnen an einem Ort versammelt haben, deutet auf eine Absicht hin.\n\nEin Wurmrufer der Neruber muss in der Nähe sein.\n\nFindet ihn und bergt das Werkzeug, mit dem sie diese Würmer herführen. Damit sollten wir sie rechtzeitig weglocken können.", sourceObjective = "Sammelt einen singenden Stein von Wurmrufer Iz'tikrine.", progress = "Ich spüre, dass noch mehr Würmer kommen. Als würden sie zu diesem Ort gezogen werden.", completion = "Was für ein merkwürdiger Edelstein.\n\nDas Lied im Inneren muss der Grund dafür sein, dass diese Würmer an diesen Ort gezogen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[78900] = { id = 78900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf kalten, dunklen Schwingen", description = "Ihr seid den Kernweg heruntergekommen, richtig? Von oben?\n\n<Toki lacht leise.>\n\nDie haben es einfach, diese Stadt-Irdenen. Hier unten kann der Tod von überall zuschlagen.\n\nVon unten. Von oben.\n\nIhr seht aus, als hättet Ihr schon so einige Viecher erledigt. Wollt Ihr Eurer Liste einen weiteren Eintrag hinzufügen?", sourceObjective = "Spürt den Schallenden Tod in Gundargaz auf.", progress = "Seid leise, das ist mein Rat.", completion = "Die monströse Fledermaus war am Ende gar nicht so monströs, was?\n\nWillkommen in Gundargaz.", sourceObjectiveStatus = "unverified-source-field" }
quests[78901] = { id = 78901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfeeeee!!!", description = "Hey! Ihr da!\n\nHolt mich hier runter! Weg von diesen Würmern! Bitte!\n\nIch bezahle Euch! Ich schulde Euch sogar was! Ich verpfeife liebend gerne jedes Kartellmitglied, das Ihr anschwärzen wollt!\n\nHolt mich hier einfach runter!\n\nUnd lauft bitte nicht zu sehr herum. Sie können Eure Schritte hören. Bewegt Euch von Fels zu Fels, wenn Ihr nicht wollt, dass ein Schwarm über Euch herfällt.", sourceObjective = "Rettet Skedgit Glutfransen.", completion = "Alles klar, in Ordnung! Es geht mir gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[78902] = { id = 78902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beauftragtes Buddeln", description = "Okay, ich weiß, wann ich mich geschlagen geben muss. Also, ich möchte Euch als meinen Champion der Münze anheuern ... als meinen Münzchamp.\n\nDas ist alles Teil meines brillanten Unternehmertums. Wisst Ihr, diese Würmer hier sind gut darin, reichhaltige Mineralien aufzuspüren, ähnlich wie die Niffen gut darin sind, hochwertige Pilze zu erschnüffeln.\n\nIch würde all mein Geld – und Euer Leben – darauf verwetten, dass sie eine Sivsteinader entdeckt haben. Tolles Zeug, auch wenn ich bezweifle, dass Ihr damit etwas anfangen könntet, {class}.\n\nIch sage Euch was, bringt mir genug für eine Lieferung, dann bekommt Ihr die Hälfte des Profits!", sourceObjective = "Besorgt 25 Sivsteinbrocken.", progress = "Habt Ihr die Waren bekommen?", completion = "Gute Ausbeute! Damit sollten wir in Mmarl Fuß fassen und diesen Ganoven zeigen können, wer hier das Sagen hat.\n\nHier ist Euer Anteil.", sourceObjectiveStatus = "unverified-source-field" }
quests[78915] = { id = 78915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kürbisbedrohung", description = "Ich brauche Eure Hilfe!\n\nDie riesigen Schattengesäuerten Kürbisse breiten sich überall aus. Sie stinken und wimmeln von widerlichen Milben.\n\nMama und Papa haben ein paar Luftschiffe mitgebracht, die uns helfen sollen, sie auszureißen, aber bei dem ganzen Ungeziefer ist das ziemlich riskant.\n\nKönntet Ihr Seile an den Kürbissen befestigen, damit die Luftschiffe sie sauber rausziehen können?", sourceObjective = "Entfernt 8 schattensaure Kürbisse und tötet 10 schattensaure Milben.", completion = "Ihr habt es geschafft! Ich habe Geschichten gehört, dass einer der Kürbisse so schwer gewesen sein soll, dass das Luftschiff abgestürzt ist. Zum Glück ist das nicht passiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[78918] = { id = 78918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brax' Messingschlagring", description = "Ich habe einen Vorschlag für Euch.\n\nWir haben hier von Zeit zu Zeit ein paar rüpelhafte Gäste. Nichts Schlimmes, aber unsere Leute arbeiten hart und die Dinge können schneller außer Kontrolle geraten als ein wild geschwungener Hammer. \n\nNormalerweise würde ich ihnen einen freundlichen Schlag auf den Kopf verpassen, um ihnen selbigen zurechtzurücken. Allerdings habe ich meinen Messingschlagring verloren, als ich Wächterin Toki beim Beseitigen der Monster am Stadtrand geholfen habe.\n\nKönntet Ihr meinen Schlagring holen und ein paar Streicheleinheiten verteilen?", sourceObjective = "Tötet Kreaturen in der Gegend von Gundargaz, um Brax' Messingschlagring finden.", progress = "Welche Bestien habe ich denn mit diesem Schlagring zuletzt vermöbelt...", completion = "Das ist das Geniale an Schlagringen. Die Hände bleiben unversehrt!", sourceObjectiveStatus = "unverified-source-field" }
quests[78929] = { id = 78929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Täuschung in der Dunkelheit", description = "Kobyss lauern in den seichten, trüben Gewässern und schnappen sich all jene, die zu nahe ans Wasser gehen, schneller als eine Viper!\n\nUnd das gilt nur, wenn sie alleine auf die Jagd gehen. Zusammen sind sie ein Schwarm, vor dem man sich wahrlich in Acht nehmen muss. Seit unserer Ankunft hier sorgen sie in den umliegenden Dörfern für Tod und Verderben.\n\nSie verspeisen ihre Opfer bei lebendigem Leibe, wenn es sich ergibt. Wir müssen die Dorfbewohner retten, die sie bereits zum Wasser gezerrt haben!", sourceObjective = "Rettet 5 gefangene Arathi.", completion = "Vielen Dank, {name}. Diese Bewohner sind schwer verletzt, aber ich glaube, sie werden es schaffen. Manche von ihnen scheinen sich selbst heilen zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[78931] = { id = 78931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Technosehen: Die Geheimnisse der Drachenschädelinsel" }
quests[78932] = { id = 78932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Furchtbar frecher Fisch", description = "Nach dem Glitzern in Euren Augen zu urteilen, möchtet Ihr Euch Faerin bei diesem Wahnsinn anschließen?\n\nIhr wollt in die Gewässer der Kobyss vordringen? In die Dunkelheit?\n\nIhr seid ein Narr mit einem Todeswunsch. \n\nSchaltet so viele dieser verdammten Fische wie möglich aus, bevor sie Euch in die Tiefen ziehen und zum Abendessen auffressen.", sourceObjective = "Tötet 13 Invasoren der Kobyss.", progress = "Wir dürfen die Dorfbewohner hier nicht im Stich lassen!", completion = "Diese Feinde sind erbarmungslos.", sourceObjectiveStatus = "unverified-source-field" }
quests[78933] = { id = 78933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die süße Eklipse", description = "Ich wollte einen Nachtisch kreieren, der das Gewöhnliche übertrifft, einen, dem selbst die treuesten Anhänger des Lichts erliegen sollten.\n\nUm die Aromen des Desserts zwischen Licht und Schatten auszubalancieren, benötige ich einzigartige Zutaten, die man nur in der Dunkelheit findet.\n\nBitte helft mir dabei und sammelt die folgenden Zutaten: froschgeküssten Kaviar, Finsterwurzelpersimone und Astralzucker.", sourceObjective = "Sammelt 8 Finsterwurzelpersimonen, 30 Stück froschgeküssten Kaviar und 1 Stück Astralzucker.", progress = "Habt Ihr alle Zutaten gefunden?", completion = "Nun wird Magie geschehen. Bitte kostet diese Kreation selbst.", sourceObjectiveStatus = "unverified-source-field" }
quests[78934] = { id = 78934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klingen der Arathi", description = "Ich vertraue auf Eure Stärke. Ich muss Euch bitten, Verstärkung in Sinas Sehnsucht zu leisten. Anduin und ich werden mein Volk bei Lorels Kreuzung in Sicherheit bringen.\n\nMeinen Leuten in Sinas Sehnsucht wird angst und bange sein wegen der Kobyss und der Dunkelheit.\n\nZündet in der Mitte der Stadt eine Fackel mit Heiliger Flamme an und entfacht somit ihren Mut. Erinnert sie daran, wie stark sie sind.\n\nWir werden dann zu Euch stoßen. Möge Euch die Flamme leiten, <mein Freund/meine Liebe>.", sourceObjective = "Entzündet eine Fackel mit der Heiligen Flamme und sammelt dann 6 Gruppen von Arathi in Sinas Sehnsucht.", completion = "Die Arathi sind stark. Stolz. Die Kobyss mögen widerwärtig sein, doch diesen Kampf werden sie heute nicht gewinnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78936] = { id = 78936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Trüben fischen", description = "Ihr Fremdlinge und Faerin habt es also tatsächlich geschafft zu überleben und die Dorfbewohner am Strand zu retten?\n\n<Stahlstoß spricht erleichtert ein kurzes Gebet.>\n\nWir stecken hier in Schwierigkeiten. Die Kobyss bedrohen das Dorf mit einigen ihrer stärksten Streitkräfte.\n\nWir haben alle Hände voll zu tun, nur die Stellung zu halten. Solltet Ihr es schaffen, diese Monster zu besiegen, könnten wir das Blatt vielleicht noch wenden.", sourceObjective = "Tötet Tiefschlammer, den monströsen Wellenbrecher und Gezeitenlord Zahnteufel in Sinas Sehnsucht.", progress = "Als wir zuerst auf die Kobyss stießen, gab es unter uns Stimmen, die Frieden mit ihnen schließen wollten. Doch es stellte sich rasch heraus, dass sie uns nur als Futter betrachten.", completion = "Jeder Arathi hat mehr Kobyss getötet, als ich zählen kann. Wir haben auch mehr Arathi an die Kobyss verloren, als ich zählen mag.\n\nKeine Ahnung, aus welcher Unterwasserhöhle sie gekrochen sind... Der bloße Gedanke daran lässt mich schaudern.", sourceObjectiveStatus = "unverified-source-field" }
quests[78937] = { id = 78937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatten über Schatten", description = "<Faerins weit aufgerissene Augen blicken sich überrascht um.>\n\nWas ist gerade passiert? Habt Ihr diesen Schatten gesehen? Und der Ölbrunnen... er hat sich verdunkelt?\n\nSo etwas habe ich noch nie erlebt.\n\nSteckt womöglich der Dämmerturm in der Nähe dahinter? Beeilt Euch!", sourceObjective = "Untersucht den nahe gelegenen Dämmerturm.", completion = "Die Furcht und Scham dieser Leute hängt wie ein Nebel in der Luft.", sourceObjectiveStatus = "unverified-source-field" }
quests[78938] = { id = 78938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion der Wasserlords", description = "Ich muss Euch leider berichten, dass eine schreckliche Bedrohung Eure Art in diesem Reich der Sterblichen erwartet. Ein Elementarlord des Feuers namens Ragnaros bereitet sich darauf vor, loszuschlagen und Azeroth bis zum Kern zu verbrennen. Wir, die Elementare des Wassers, führen seit Ewigkeiten Krieg gegen diese niederen Elementare. Seid Euch sicher, dass unsere Warnung nicht leichtfertig erfolgt.\n\nBeweist Eure Hingabe! Tötet Ragnaros ein für alle Mal!", sourceObjective = "Besiegt den unvergessenen Ragnaros bei einem \"Strahlende Echos\"-Ereignis.", progress = "Ragnaros bleibt bestehen, Sterblicher. Seine üble Hitze strahlt in der Nähe aus.", completion = "Ihr habt getan, was die meisten Eurer Art für unmöglich hielten. Ihr habt Euch Ragnaros gestellt und triumphiert!\n\nFür eine so kleine Kreatur habt Ihr großen Mut bewiesen.\n\nEines Tages könnte ein echtes Bündnis zwischen Eurer Art und den Wasserlords entstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78939] = { id = 78939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verdunkelte Flamme", description = "Dieser... Orden der Nacht, wie er sich selbst nennt, hat die Flamme des Turms mithilfe eines widerwärtigen Rituals in Dunkelheit verwandelt. Was es war, weiß ich nicht.\n\nWir sollten einmal nachsehen.", sourceObjective = "Seht Euch am verdunkelten Dämmerturm um.", progress = "Mein eigenes Volk... Wie konnte es nur?\n\n<Faerin schüttelt ungläubig ihren Kopf.>", completion = "Sie haben also auch Kelther getötet?\n\n<Faerin kneift die Augen zusammen und murmelt ein stilles Gebet und einen Fluch zugleich.>\n\nWir bereiten ihm eine angemessene Beerdigung. Der Orden der Nacht wird dafür bezahlen.\n\nWir haben Düsterfelsen, die nahegelegene Höhle, schon vor Jahren versiegelt. Offenbar haben sie sich ihren Weg hinein gegraben, um es auf diesen Dämmerturm abzusehen.\n\nWie lange haben sie das geplant? Wie lange hat sich der Orden der Nacht schon unter unsere Reihen gemischt?", sourceObjectiveStatus = "unverified-source-field" }
quests[78940] = { id = 78940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quest 00" }
quests[78941] = { id = 78941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein zu wendendes Blatt", description = "Xal'ataths Armee versetzt uns schon seit einiger Zeit empfindliche Schläge. Was hat sie also bewogen, diesen Moment zu wählen?\n\nIrgendetwas stimmt hier nicht. Sie hat darauf gewartet, dass wir als Reaktion darauf ein Heer ausheben, und greift uns dann offen an. Wir spielen ihr in die Hände.\n\nMeldet Euch bei der Generalin der Arathi. Ich werde mich direkt zum Schlachtfeld begeben.", sourceObjective = "Trefft Generalin Stahlstoß in Heilsturz.", completion = "Gut, Ihr seid hier. Ich fasse mich kurz.", sourceObjectiveStatus = "unverified-source-field" }
quests[78942] = { id = 78942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht von Khaz Algar", description = "Die Vorbotin denkt, sie kann uns überrumpeln, aber sie ist eine Närrin, wenn sie in diesem Kampf einen Sieg erwartet.\n\nDie Algarioffensive deckt Euch den Rücken, {name}. Verschont keinen Feind.", sourceObjective = "Schlagt die Neruber zurück.", completion = "Eure Horde und Allianz sind eine beeindruckende Armee. Ich glaube, ohne sie hätten wir es nicht so weit gebracht.", sourceObjectiveStatus = "unverified-source-field" }
quests[78943] = { id = 78943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stahl und Flammen", description = "Unsere Streitkräfte können ihre Positionen vielleicht halten, aber Euch im Gefecht zu sehen, könnte gut für die Moral sein.\n\nNehmt dieses Kriegshorn. Lasst es erschallen und erfüllt unsere Feinde mit Schrecken. Begebt Euch zu Euren Kommandanten, sobald Ihr unsere Truppen ermutigt habt.", sourceObjective = "Versammelt 20 Truppen der Algarioffensive.", completion = "Ihr kommt gerade rechtzeitig.", sourceObjectiveStatus = "unverified-source-field" }
quests[78948] = { id = 78948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Licht in der Dunkelheit", description = "Irgendetwas stimmt hier ganz und gar nicht. Je länger der Kampf andauert, desto aggressiver werden beide Seiten.\n\nAlleria scheint etwas zu wissen - sie ist mitten im Kampf einfach davongestürmt. Wir sind ihr hinterher geeilt, aber ich kann diese Soldaten hier nicht ihrem Tod überlassen. Sie ist nur ein Stückchen weiter, wir können uns mit ihr treffen.", sourceObjective = "Sprecht mit Anduin und macht Jagd auf Xal'atath.", completion = "Khadgar braucht sofortige Hilfe. Wir haben später noch Zeit zum Feiern.", sourceObjectiveStatus = "unverified-source-field" }
quests[78950] = { id = 78950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ab mit den Beinen", description = "Wir konnten Xal'atath noch nicht aufspüren, aber uns erreichten Berichte von tiefer aus dem Feld, dass bestimmte Neruber die Befehle geben. Das bringt uns nicht allzu viel, aber jede Aktion ist entscheidend.\n\nSchaltet sie aus. Hoffentlich verschafft uns das etwas Luft zum Atmen.\n\nSprecht mit Anduin, wenn Ihr es erledigt habt. Er und das Arathimädchen eilten Alleria hinterher.", sourceObjective = "Tötet die Leutnants der Neruber.", progress = "Sprecht mit Anduin in der Blutigen Umarmung.", completion = "Oh gut, Ihr habt es geschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[78951] = { id = 78951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein immer tieferer Schatten", description = "Als ich nach der Flamme langte, spürte ich die überwältigende Hoffnungslosigkeit und Verzweiflung, die in sie gegossen wurden.\n\nEs schmerzt mich, aber... mein Licht allein reicht nicht aus, um diese Schatten zu verbannen.\n\nWir müssen also einen direkteren Weg wählen. Wenn sich die verbleibenden Kultisten in die Düsterfelsenlaube zurückgezogen haben, verdunkelt ihre gemeinsame Macht vermutlich die Flamme.\n\nWir müssen sie aufhalten, bevor sich die Dunkelheit weiter ausbreitet.", sourceObjective = "Tötet 10 Kultisten vom Orden der Nacht in der Höhle unter dem Felsklippenleuchtfeuer.", progress = "Sie waren einst meine Brüder und Schwestern. Meine Verbündeten. Meine Mentoren.\n\nIch habe versucht, sie zur Vernunft zu bringen. Damit sie das Licht sehen... sehen, dass das Licht noch immer in uns allen steckt.\n\n<Faerins Gesichtsausdruck wechselt zwischen Trauer und Wut.>\n\nSie wollten nicht zuhören. Und sie töten Unschuldige.\n\nIch darf nicht zögern. Nicht mehr.", completion = "<Faerin lässt die Kiefer mahlen.> \n\nSie haben ihre Wahl getroffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78952] = { id = 78952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Widerstand", description = "<Faerin entfährt ein unterdrücktes, zorniges Flüstern.>\n\nGute Arbeit. Aber bevor wir gehen, müssen wir noch etwas erledigen.\n\nAm Ende dieses Wegs gibt es ein paar mächtige Priester, die, so glaube ich, etwas beschwören. Etwas Großes, das uns sicher von oben angreifen und vom Turm forttreiben soll.\n\nDas wird gefährlich, aber wir müssen sie aufhalten. Seid Ihr dabei?", sourceObjective = "Zerstört den Schattenriss.", completion = "<Faerins Augen sind trüb vor Erschöpfung.>\n\nEs hört nie auf, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[78954] = { id = 78954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flamme wiederherstellen", description = "Spürt Ihr es? Wie die Hoffnung zurückkehrt?\n\nDanke für Eure Hilfe, {name}.\n\nDie Flamme des Dämmerturms ist noch dunkel. Aber ich glaube, diesmal gelingt es uns, sie wieder zum Leuchten zu bringen.\n\nTreffen wir uns am Turm.", sourceObjective = "Helft Faerin, die Heilige Flamme des Felsklippenleuchtfeuers wiederherzustellen.", progress = "Ich hoffe inständig, dass wir gemeinsam etwas mehr Licht in unsere kleine Welt bringen können.", completion = "<Faerin lässt ein müdes, aber warmes Lächeln aufblitzen.>\n\nDanke. Ich danke dem Licht, dass Ihr alle erschienen seid. Ich bin froh, dass wir einander helfen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[78972] = { id = 78972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erntechaos", description = "Unsere Eltern sind losgezogen, um die Monster zu bekämpfen, die unseren Hof überfallen haben. Wir versuchen den Hof in ihrer Abwesenheit am Laufen zu halten. \n\nWir haben einen Erntebot, der uns bei der Arbeit hilft, aber ich lenke ihn immer wieder ins Wasser. Wir könnten unsere Arbeit beenden, wenn Ihr uns helft, den Erntebot zu steuern!", sourceObjective = "Steuert Erntebot Remy, um 4 Kohlköpfe und 4 Karotten in Wagen zu laden. Tötet außerdem 12 invasive Käfer.", progress = "Habt Ihr die Aufgaben erledigt?", completion = "Ihr habt Rémy wirklich gut gelenkt. Vielleicht könnt Ihr nächste Woche wiederkommen und helfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[78974] = { id = 78974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles für den Käfer" }
quests[78978] = { id = 78978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stinker großziehen", description = "Hinter den von uns gefundenen Hinweisen steckt eine hässliche Geschichte, {name}.\n\nDie Karte zeigt, dass die Chemiemanufaktur Krone über eine schwer bewachte Operationsbasis im Silberwald verfügt. Und aus dieser Notiz und der Formel geht hervor, dass sie weiß, wie man etwas berauschend Toxisches zubereitet.\n\nIch kenne eine Person, die uns... handgemachte Produkte... zur Bekämpfung von Krone besorgen kann. Ich unterhalte mich mit ihr, und wir treffen uns dann vor der Burg Schattenfang.", sourceObjective = "Trefft Euch mit Detektiv Schnappbolz am Eingang der Burg Schattenfang im Silberwald.", completion = "Da seid Ihr ja, genau rechtzeitig.\n\nIch habe einen Plan für den Umgang mit dieser chemischen Konspiration.", sourceObjectiveStatus = "unverified-source-field" }
quests[78979] = { id = 78979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Selbstliebe auf die eigene Art", description = "Für die Dauer der Gala komme ich im Gasthaus von Klingenhügel unter. Das sieht zwar nicht nach viel aus, ist aber überraschend gemütlich!\n\nWarum fragt Ihr dort nicht, ob es überzählige Betten gibt, die Ihr verwenden könnt?\n\nIch glaube, ich werde mich auch etwas ausruhen... Genau... hier...", sourceObjective = "Macht ein Nickerchen im Gasthaus von Klingenhügel.", progress = "<Ning schnarcht sanft.>", completion = "Hä? Oh! Willkommen zurück, habt Ihr Euch schön ausgeruht?\n\nTäglich verrichtet Ihr für andere große Taten.\n\nHeute habt Ihr etwas Großes für Euch getan. Und das ist beste Geschenk von allen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78980] = { id = 78980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfach herumstöbern", description = "Hier auf der Gala der Geschenke haben wir viele wunderbare Kunsthandwerkergeschenke eigens für Euch und Eure Lieben. Aber Ihr müsst mir nicht einfach so glauben. Es gibt viele weitere Besucher, die die Festlichkeiten ebenfalls genießen!\n\nNur zu, sprecht mit den Besuchern und seht, was die Kunsthandwerker anzubieten haben. Vielleicht findet Ihr das perfekte Geschenk!", sourceObjective = "Besucht die Händler und Besucher auf der Gala der Geschenke.", completion = "Wie Ihr seht, gibt es zahleiche tolle Geschenke dort!\n\nBesorgt ein Geschenk für jemanden, der Euch am Herzen liegt!", sourceObjectiveStatus = "unverified-source-field" }
quests[78981] = { id = 78981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liebe liegt in der Luft", description = "Riecht mal an diesen Rosen! Meine Partnerin hat sie für mich bei der Gala der Geschenke besorgt.\n\nWollt Ihr Euch das selbst ansehen? Geht nach Durotar. Es gibt Geschenke... und Essen, und Ihr solltet die Schokolade kosten, sie ist köstlich!", sourceObjective = "Besucht die Gala der Geschenke in Durotar in der Nähe des Felshauerhofs.", completion = "Willkommen auf der Gala!\n\nMöchtet Ihr mehr über meine Schokoladenspezialitäten erfahren?", sourceObjectiveStatus = "unverified-source-field" }
quests[78982] = { id = 78982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das riecht nach Ärger", description = "Ihr riecht diesen komischen Geruch auch? Riecht wie Rauch, billiges Duftwasser und alchemistischer Unfug. Wenn Ihr mich fragt, ich glaube, die Chemiemanufaktur Krone heckt irgendwas aus. Wollt Ihr mir helfen, der Sache auf den Grund zu gehen?\n\nTja, dann seht mal her! Sieht aus wie ein stinknormaler Köter, aber das ist O.D.I.E., das Olfaktorische Detektions- und Identifikations-Exemplar! Mit diesem kleinen Helfer können wir 10 km gegen den Wind erschnüffeln, was Krone im Schilde führt!\n\nSeid Ihr dabei? Ich könnte einen guten Partner brauchen, um das Rätsel zu lösen.", sourceObjective = "Nutzt O.D.I.E.s Fernsteuerung, um Hinweise in Orgrimmar zu finden.", progress = "Klar, O.D.I.E. kann die Hinweise erschnüffeln, aber Ihr müsst sie schon zu einem Bild zusammenfügen.", completion = "Giftiges Parfüm? Rache dafür, dass sie aus der Stadt geworfen wurden?\n\nKlingt so, als würde Apotheker Hummel irgendwas Finsteres auskochen. Das könnte hässlich enden.", sourceObjectiveStatus = "unverified-source-field" }
quests[78983] = { id = 78983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein unliebsames Geschenk", description = "Ich habe so den Verdacht, dass sich Spione der Chemiemanufaktur Krone unters Volk gemischt haben. Zum Glück weiß ich auch, dass Ihr wisst, dass O.D.I.E. hier weiß, wie wir ihnen auf die Geruchsspur kommen!\n\nAber wir brauchen ja niemanden zu belästigen, der einfach ein bisschen entspannen will, klar? Also haltet die Nase nur nach Chemikalien offen und stellt sicher, dass wir die richtigen Ziele treffen.", sourceObjective = "Tötet 8 Mitglieder von Chemiemanufaktur Krone in Orgrimmar.", progress = "Immer der Nase nach, Kumpel! Jeder, der müffelt, könnte verdächtig sein!", completion = "Herrje, {name}, Ihr mieft!\n\n\n\nSchlimmer noch! Ich miefe!\n\nNa, wenigstens haben wir der Gala ein bisschen Frieden beschert. Wir wollen ja nicht, dass Krone die Feier verdirbt.", sourceObjectiveStatus = "unverified-source-field" }
quests[78984] = { id = 78984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone zerschmettern", description = "Sieht aus, als hätte Hummel Sicherheitsleute angeheuert. Aber keine Sorge, ich hab ein paar spezielle \"Geschenke\" dabei.\n\n<Schnappbolz zeigt auf die unbeschriftete Kiste.>\n\nBomben. Ich hab Bomben dabei.\n\nJetzt ist Schluss mit lustig. Nehmt diese Bomben und jagt damit Krone und ihre Vorräte in die Luft. Zeigt ihr, was ehrliche Handarbeit bedeutet. Sobald wir ihrem schmutzigen Geschäft das Handwerk gelegt haben, können wir uns um Hummel kümmern.", sourceObjective = "Nutzt die Handwerk-Bon-Bomben, um Vorräte der Chemiemanufaktur Krone zu zerstören und Mitglieder der Chemiemanufaktur Krone auszuschalten.", completion = "Junge, ich steh so sehr auf gutes Feuerwerk! Hervorragende Arbeit, {name}. Das dürfte sie wenigstens etwas ausbremsen.\n\nJetzt müssen wir uns nur noch um Hummel kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[78985] = { id = 78985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gestank der Rache", description = "Das wird erst vorbei sein, wenn wir den Boss ausschalten.\n\nApotheker Hummel hat sich mit seinen Spießgesellen in der Burg Schattenfang verschanzt. Er arbeitet an der nächsten Charge von giftigem Parfüm und er wird damit ganz Orgrimmar auslöschen, wenn wir ihn seine Forschung durchziehen lassen.\n\nIhr macht am besten das, was Ihr am besten könnt. Dringt dort ein und durchkreuzt seine Pläne, bevor wir alle als Leichen mit Lavendelduft enden.", sourceObjective = "Sprecht mit Schnappbolz, um an dem Kampf gegen die Chemiemanufaktur Krone teilzunehmen und Apotheker Hummel zu besiegen.", completion = "Klingt, als wärt Ihr gerade noch rechtzeitig dort eingetroffen. Fantastische Arbeit!\n\nHätte Hummel die gesamte Gala vergiftet, hätte das richtig übel werden können.\n\nSagen wir einfach, dass das unser Geschenk an sie ist, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[78986] = { id = 78986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausflug in die malerischen Grizzlyhügel!", description = "Guten Morgen! Das heutige Sonderportal ist ein magischer Ausflug in die majestätischen Wälder von Nordend!\n\nObwohl, könnte ich Euch um einen Gefallen bitten? Ihr seht sehr abenteuerlustig aus.\n\nIch könnte Eure Hilfe bei der Lieferung einiger Blumen aus den Grizzlyhügeln an eine wunderschöne Dame namens Laverne brauchen.\n\nIch würde es selbst tun, aber... Nun, Ihr müsst verstehen, ihre Schönheit ist recht einschüchternd.", sourceObjective = "Nehmt das Portal für malerische Ausflüge in die Grizzlyhügel, um einen Blumenstrauß für Laverne zu pflücken.", progress = "Die Magierin, die die Portale beschwört?\n\n<Laverne kichert.>\n\nLasst mich mal sehen.", completion = "Diese Gala ist wirklich wunderbar, um neue Entdeckungen zu machen...\n\n<Laverne spielt gedankenverloren mit den Blumen, während sie zu Aurora hinüberstarrt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[78987] = { id = 78987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausflug ins malerische Nagrand!", description = "Guten Tag! Das heutige Sonderportal ist ein magischer Ausflug zu den beeindruckenden Ebenen Nagrands!\n\nWärt Ihr vielleicht an einem Vorschlag interessiert? Ich werde Euch meine Kamera leihen, wenn Ihr die Fotos, die Ihr macht, meinem lieben Freund Karn bringt.\n\nEr wandert letzthin in Nagrand herum, in seinen eigenen Gedanken verloren. So stur er auch ist, er würde sich bestimmt über Eure Gesellschaft freuen. Ich würde es selbst tun, aber ich muss die Portale hier aufrechterhalten.", sourceObjective = "Nehmt das Portal für malerische Ausflüge nach Nagrand und macht dort Aufnahmen von Wildtieren für Karn.", completion = "Er hat Euch WORUM gebeten?\n\nEr weiß, dass Laverne... ARGGH! Ich habe das wohl nicht anders verdient, schätze ich, nachdem ich dem Ruf meines eigenen Herzens nicht früher gefolgt bin.\n\nNun, das ist unwichtig. Alles ist gut, Aurora, das ist in Ordnung...\n\nÄh, ich danke Euch dennoch, {name}. Die Dornen meiner Rosen sollten nicht in Euren Händen ruhen. Ich werde einen anderen Weg finden, Lavernes Aufmerksamkeit zu erregen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78988] = { id = 78988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausflug ins malerische Feralas!", description = "Guten Tag! Das heutige Sonderportal ist ein magischer Ausflug zu den sonnigen Stränden von Feralas! Im Hotel an den Dampfteichen wird ein wunderbares Fest gefeiert, und alle sind eingeladen!\n\nLeider haben einige der Festivalbesucher, die schon durch das Portal sind, ihre Geschenke hier auf der Gala vergessen.\n\nKönntet Ihr mir vielleicht helfen, sie ihnen zu bringen? Ich treffe Euch am Strand und zusammen finden wir heraus, welches Geschenk wem gehört.", sourceObjective = "Nehmt das Portal für malerische Ausflüge nach Feralas und bringt die vergessenen Geschenke zu den entsprechenden Empfängern.", progress = "Es gibt so viele Orte in Azeroth für einen Ausflug! Überall, wohin man schaut, gibt es etwas Neues zu entdecken.", completion = "Ihr seid wunderbar hilfreich, {name}. Ihr habt die Laune vieler Leute angehoben, indem Ihr ihnen ihre Geschenke gebracht habt.\n\nUnd was das für eine Sammlung von Geschenken war! Vielleicht sieht die Sprache der Liebe für jeden anders aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[78989] = { id = 78989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gabe der Selbstfürsorge", description = "Die Augen eines müden Abenteurers.\n\nJemand, der zu viel Großartiges für andere getan hat. Wann war das letzte Mal, dass Ihr Euch selbst etwas Gutes getan habt?\n\nVielleicht ist die Zeit jetzt gekommen. Erkundet Euer Herz.\n\nWas ist EUER Begehr?", sourceObjective = "Sprecht mit Ning, um Euren Herzenswunsch zu entdecken.", progress = "Die Liebe ist ein Segen, besonders wenn sie von innen kommt.", completion = "Treten wir Eure Reise zur Selbstliebe an.", sourceObjectiveStatus = "unverified-source-field" }
quests[78990] = { id = 78990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gabe der Erholung", description = "Ihr Abenteurer seid dafür bekannt, schwere Bürden zu schultern. Es gibt keinen besseren Zeitpunkt als jetzt, um sich ihnen zu stellen.\n\nIch habe hier irgendwo in der Nähe einen Veteranen gesehen. Es besteht die Möglichkeit, dass er weiß, was es heißt, Stress zu bewältigen.\n\nVielleicht gibt es etwas, dass er Euch beibringen kann.", sourceObjective = "Sprecht mit Tokag Knochenbrecher auf der Gala der Geschenke und baut dann Euren Stress in Orgrimmar ab.", completion = "Fühlt Ihr Euch besser?\n\nIhr müsst Euch nach einem schweren Tag um Euren Körper kümmern. Seid gut zu Eurem Kopf und Herzen, dann wird beides gut zu Euch sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[78991] = { id = 78991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gabe der Entspannung", description = "Die Liebe ist ein Geschenk, ja. Doch sie ist auch ein Geschenk, das Ihr Euch selbst machen könnt.\n\nManchmal liebt man sich am besten durch einfache Entspannung.\n\nIch habe auf der anderen Seite des Südstroms eine Trollfrau getroffen, die in dieser Hinsicht besonders erfahren zu sein scheint. Vielleicht bittet Ihr sie um einen Einblick in die Kunst der Entspannung.", sourceObjective = "Sprecht mit Jaz der Wiedergeborenen über Entspannung und entspannt Euch dann am Südstrom im Nördlichen Brachland.", completion = "Jetzt fühlt Ihr Euch erneuert, was? Wir müss'n uns alle von den Problemen in unsren Leben erhol'n.\n\nEntspannen hat mir geholfen, mich selbst wiederzuentdeck'n. Hat mein ganzes Leben verändert. Ich hatte Hauer bis hier und 'nen Iro, buahaha! Wie dumm ich doch war.\n\nHabt Ihr was über Euch selbst entdeckt?", sourceObjectiveStatus = "unverified-source-field" }
quests[78992] = { id = 78992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Selbstliebe auf die eigene Art", description = "Wenn Ihr Euch für solch eine Herausforderung interessiert, habe ich eine Idee.\n\nIch habe einen prahlerischen Champion auf dem Weg nach Klingenhügel gesehen. Ihr könntet ihn zu einem Duell herausfordern.\n\nDas würde Eurem Wunsch gerecht werden, und Ihr könntet ihm eine wertvolle Lektion in Demut erteilen.", sourceObjective = "Besiegt Poggtucker Zornwerfer in einem Duell nahe der Straße nach Klingenhügel.", progress = "Wie läuft Eure Herausforderung?", completion = "Täglich verrichtet Ihr für andere große Taten.\n\nHeute habt Ihr etwas Großes für Euch getan. Und das ist beste Geschenk von allen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78993] = { id = 78993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Selbstliebe auf die eigene Art", description = "Ein voller Bauch ist ein glücklicher Bauch!\n\nHier auf der Gala gibt es jede Menge köstliche Speisen und Getränke. Kauft Euch doch etwas Schönes, was meint Ihr?", sourceObjective = "Verzehrt Pakete mit Köstlichkeiten von Händlern auf der Gala der Geschenke.", progress = "Habt Ihr genügend leckere Speisen vertilgt? Ich für meinen Teil mag Obst sehr gerne.", completion = "Täglich verrichtet Ihr für andere große Taten.\n\nHeute habt Ihr etwas Großes für Euch getan. Und das ist beste Geschenk von allen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78995] = { id = 78995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trüffelei" }
quests[78996] = { id = 78996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen und Krieger", description = "Gorlocrotten haben diese Bauern abgeschlachtet und ihre Perlen gestohlen. Sie haben uns um Hilfe angesucht, aber auch unsere Kräfte reichen womöglich nicht.\n\nIch kenne andere in der Nähe, die helfen könnten. Sucht sie auf und bittet sie um Unterstützung. Falls sie zögern, könnt Ihr ihnen Perlen als Bezahlung anbieten.\n\nWir müssen auch die Bauern bewaffnen, damit sie sich selbst verteidigen können. Haltet nach entbehrlichen Waffen und Rüstungen Ausschau, die sie nutzen können.\n\nIch begleite die Bauern und bilde sie so gut es geht an der Waffe aus.", sourceObjective = "Sammelt 3 Waffenkisten und rekrutiert 5 Krieger aus Freyholtz und Dhar Dhurgaz.", completion = "Gute Arbeit. Ich bin froh, dass Ihr einige Kämpfer rekrutieren konntet. Es ist schlimmer, als ich befürchtet hatte. Wir brauchen wirklich jede Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[78997] = { id = 78997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geplünderte Perlen", description = "Die Perlen, die diese Bauern ernten, sind ihre einzige Einnahmequelle. Einige dieser Irdenen betrachten die Perlenernte gar als ihren Hauptdaseinszweck.\n\nDie Gorlocs plündern die Perlen weiterhin bei jeder Gelegenheit. Wenn ihr sie zur Strecke bringt, sucht bitte auch nach gestohlenen Perlen. Wir sollten so viele retten, wie wir können.", sourceObjective = "Erlangt 8 gestohlene Perlen von Gorlocs an der Schimmernden Küste zurück.", progress = "Wir müssen die Perlen den Bauern zurückgeben.", completion = "Ich danke Euch, {name}. Die Bedrohung durch die Gorlocs auszuschalten, war nur eines unserer Ziele. Das andere ist, den Bauern ihr Leben zurückzugeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[78998] = { id = 78998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauern an die Front", description = "Die meisten Bauern stehen bereits auf dem Schlachtfeld und verteidigen ihre Positionen. Ich habe sie ausgebildet, so gut es die Umstände zuließen, aber noch schwingen sie nur ihre Bauerswerkzeuge.\n\nBitte verteilt die Waffen, die Ihr gesammelt habt, an der Front. Das macht die Bauern auch nicht kampftüchtiger, aber vielleicht verschafft es ihnen etwas Mut, wenn sie wissen, dass sie nicht allein in diesem Kampf sind.", sourceObjective = "Verteilt 3 Waffenkisten an die Perlenbauern an der Schimmernden Küste.", completion = "Ausgezeichnet. Solange sie gemeinsam und für einander kämpfen, werden sie siegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78999] = { id = 78999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herz eines Helden", description = "Wie es scheint, haben die Gorlocs ihre Truppen mit beschworenen Elementaren verstärkt. Das erklärt, warum sie die Bauern so mühelos überrennen konnten.\n\nEs wird all unsere Kräfte erfordern, um die Kolosse aufzuhalten, die bereits auf dem Schlachtfeld sind. Bitte verhindert Ihr derweil, dass neue Elementare geschaffen werden.\n\nElementare dieser Größe können nur von den mächtigsten Gorlocschamanen beschworen werden. Macht sie hinter den Feindeslinien ausfindig und erledigt sie.\n\nDamit sollten wir diese Gorlocgeißel für die Bauern ein für alle Mal beenden.", sourceObjective = "Bezwingt die drei Gorlocschamanen-Anführer.", completion = "Vielen Dank für Eure Hilfe, Fremdling. Ohne Euch wäre all das nicht möglich gewesen. Ihr habt uns heute unseren Lebensunterhalt zurückgegeben, und unsere Hoffnung.\n\nBitte nehmt dies als kleines Zeichen unserer Dankbarkeit. Es wird Eurer Hilfe kaum gerecht, aber es ist alles, was wir anbieten können. Unser Volk wird Euch für immer willkommen heißen.\n\nNun sollten wir unsere Aufmerksamkeit aber Aggartha zuwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[79006] = { id = 79006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fraktionswechsel", description = "Standard" }
quests[79009] = { id = 79009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vorbotin", description = "Wir benötigen erneut Eure Hilfe, Champion. Eine geheimnisvolle Gestalt schleicht durch die Schatten. Die Vorbotin...\n\nSprechen wir in der Kammer des Wächters. Ich habe Alleria gebeten, uns ebenfalls dort zu treffen.", sourceObjective = "Trefft Khadgar und Alleria an der Kammer des Wächters in Dalaran.", progress = "Ein strahlender Gesang, ein dunkles Herz und diese geheimnisvolle Vorbotin... Was kann das alles nur bedeuten?", completion = "Wir wissen, dass Iridikron das dunkle Herz der Vorbotin übergab. Aber was das dunkle Herz ist und was die Vorbotin damit vorhat... das alles ist noch unbekannt.\n\nUnd der strahlende Gesang. Der Zeitpunkt ist kein Zufall.\n\nDiese Angelegenheit kann nicht länger warten. Darum habe ich Euch und Alleria gebeten, dies zu untersuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79010] = { id = 79010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tor zu den Ren'dorei", description = "Wenn es bei dieser Untersuchung um die Leere geht, wäre es weise, die Leerenelfen um Rat zu fragen. Wir müssen zum Telogrusriss reisen und über die Lage berichten.\n\nIch werde mit Umbric reden. Er wird die Risswanderer für unsere Sache mobilisieren können.", sourceObjective = "Folgt Alleria zum Telogrusriss.", completion = "Wir werden die Berichte der Risswanderer hören müssen, bevor wir unsere eigene Untersuchung beginnen. Vielleicht erfahren wir etwas, das uns sagt, wo wir beginnen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[79011] = { id = 79011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Risswandererberichte", description = "Die Risswanderer haben die Aufgabe, alle Aktivitäten der Leere in Azeroth zu untersuchen. Eine enorm wichtige Pflicht, bedenkt man, wie gefährlich diese dunkle Macht sein kann. Und ich spreche aus Erfahrung.\n\nViele von ihnen wurden ausgesandt, um die kürzlichen Veränderungen zu untersuchen. Man sagte mir, dass sie vor Kurzem zurückkehrten, aber wir müssen ihre Berichte noch anhören.\n\nKönntet Ihr nach ihnen sehen, während ich mit Alleria spreche?", sourceObjective = "Sammelt Berichte von den Risswanderern im Telogrusriss.", progress = "Lasst mich wissen, wenn Ihr diese Risswandererberichte habt.", completion = "Danke, dass Ihr die Berichte gesammelt habt. Leider ist die Risswanderin aus Nordend noch nicht zurückgekehrt.\n\nSie hat die Leerenaktivität in Galakronds Ruhestätte untersucht. Bedenkt man die Verbindung, die dieser Ort zum dunklen Herz hat, würde ich vorschlagen, dass Ihr nach ihr sucht.\n\nWir wollen hoffen, dass unsere Risswanderin noch dort ist, um Euch ihren Bericht zu geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[79012] = { id = 79012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Risse in der Leere", description = "Der Telogrusriss war immer außerordentlich empfindlich gegenüber kosmischen Veränderungen. Als Zuhause ist er daher etwas gefährlich, aber die Leerenelfen haben... nur wenige Optionen.\n\nDer kürzliche Anstieg von Leerenenergien hat dazu geführt, dass sich sporadisch instabile Risse öffnen. Und weil so viele Risswanderer Azeroth durchsuchen, habe ich Schwierigkeiten, jemanden zu finden, der sich um die Risse kümmert.\n\nKönntet Ihr alle instabilen Leerenrisse schließen, denen Ihr unterwegs begegnet?", sourceObjective = "Schließt 5 instabile Leerenrisse im Telogrusriss.", progress = "Normalerweise würden die Risswanderer sich um derartige Anomalien kümmern. Aber ich möchte sie nicht von ihren laufenden Untersuchungen ablenken.", completion = "Ausgezeichnete Arbeit.\n\nDiese instabilen Leerenrisse bedrohen mehr als nur unsere Realität. Wenn wir uns nicht um sie kümmern, könnten sie sich wild verbreiten wie kleine kosmische Prionen. Keine Realität, keine Möglichkeit, keine Wahrheit, die irgendwie sein könnte, wäre vor ihnen sicher.\n\nMit anderen Worten, Ihr habt uns einen großen Gefallen getan, indem Ihr sie geschlossen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[79013] = { id = 79013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Galakronds Unruhestätte", description = "Galakronds Ruhestätte. Wo das dunkle Herz erstmals von Iridikron mit Macht erfüllt wurde. Wir wissen nicht, welche Macht in dem Relikt ruht, aber wir wissen, dass die Vorbotin es nun trägt.\n\nUnd nun wird eine unserer Risswanderinnen vermisst, genau dort, wo alles begann.\n\nIch glaube nicht, dass dies ein Zufall ist, {name}. Reisen wir nach Nordend und durchsuchen die Umgebung.", sourceObjective = "Trefft Alleria bei Galakronds Ruhestätte in der Drachenöde.", completion = "Zeit, unsere Risswanderin zu finden. Und wenn wir Glück haben, finden wir auch einen Hinweis auf das dunkle Herz und diese Vorbotin, die es trägt.", sourceObjectiveStatus = "unverified-source-field" }
quests[79014] = { id = 79014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In ihren Schatten", description = "Ich arbeite nicht oft mit den Risswanderern zusammen und ziehe es vor, meine Missionen alleine zu erledigen. Dennoch werde ich niemanden von ihnen im Stich lassen.\n\nIch kann die Gegenwart der Risswanderin noch nicht spüren. Wir sollten am besten ihren Spuren folgen.\n\nWas bedeutet, den Schatten zu folgen.", sourceObjective = "Entdeckt die Präsenz der Leere bei Galakronds Ruhestätte in der Drachenöde.", completion = "Wir wissen jetzt, warum die Risswanderin nicht Bericht erstattet hat. Sie hat sich gegen uns gewendet und dient nun nur noch der Leere.\n\nAuch wenn es mich nicht überraschen würde, wenn die Vorbotin ihre Hand im Spiel hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[79015] = { id = 79015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkler Abstieg", description = "Was tun diese Leerenbruten hier? Ist das das Werk der Vorbotin? Eine Kraft vom dunklen Herz?\n\nGut. Ich werde nicht tatenlos zusehen.\n\nWir müssen die Risswanderin stellen. Ich glaube nicht, dass sie noch Vernunft annehmen wird, aber vielleicht kann sie uns etwas verraten.", sourceObjective = "Stellt die vermisste Risswanderin.", progress = "Was kann die Vorbotin mit Ulduar wollen?", completion = "Es ist meine Aufgabe, den Ren'dorei beizubringen, dem Flüstern der Leere zu widerstehen. Wenn ich die Risswanderin nur vor der Vorbotin erreicht hätte...\n\nNilara. Ihr Name war Nilara, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[79016] = { id = 79016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermächtnis der Leere", description = "Glaubt mir, {name}. Ich weiß, dass es eine Falle ist. Aber wenn die Möglichkeit besteht, dass dies uns zur Vorbotin führt, müssen wir das Risiko eingehen.\n\nMacht Euch bereit. Wir setzen unsere Reise fort.", sourceObjective = "Reist zum Konservatorium der Triade in Eredath.", completion = "Eredath. Ich hätte nie gedacht, einmal hierher zurückzukehren. Nicht nach dem endgültigen Sieg über die Legion. Nicht nach...\n\nWarum sollte die Vorbotin uns hierherbringen?", sourceObjectiveStatus = "unverified-source-field" }
quests[79017] = { id = 79017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gewählte Pfad", description = "Diese Erscheinungen vor uns. Ich glaube, es sind... Erinnerungen. Meine Erinnerungen. Ist das das Werk der Vorbotin? Oder meines?\n\nWir müssen uns umsehen. Herausfinden, warum wir hierhergeführt wurden.", sourceObjective = "Bezeugt Allerias Erinnerungen in Eredath.", progress = "Plötzlich erscheint mir das alles sehr persönlich. Die Vorbotin muss einen Groll gegen mich hegen. Oder zumindest... Interesse an mir haben. Hm.", completion = "Wir finden die Vorbotin und verlassen diesen Ort. Jetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[79018] = { id = 79018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und als Reisende stand ich lang", description = "Ich spüre da vorne eine weitere Erinnerung.\n\nAuch wenn ich keinesfalls nach den Regeln der Vorbotin spielen will, ist das der einzige Weg, den wir gehen können.\n\nDennoch sind uns ebenso viele gefährliche Erinnerungen wie friedliche begegnet. Macht Euch bereit.", sourceObjective = "Untersucht die letzte Erinnerung beim Konservatorium der Triade in Eredath.", completion = "Die Vorbotin wagt es, mein Volk, meine Erinnerungen, meine Liebe gegen mich einzusetzen?\n\nDann wird sie erfahren, was es bedeutet, meine Feindin zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[79019] = { id = 79019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung des Telogrusrisses", description = "Nein. Nicht die Ren'dorei. Nicht der Telogrusriss. Nicht heute.\n\n<Alleria greift ihren Bogen fester.>\n\nDiese Astralkräfte sind die gleichen, die uns in Ulduar begegnet sind. Die Vorbotin muss sie kontrollieren.\n\nIch gehe voraus. Greift die Gegner hier an.", sourceObjective = "Verteidigt den Telogrusriss.", completion = "Diese Leerenbruten nehmen kein Ende. Aber vorerst müssen wir unsere Aufmerksamkeit auf einen anderen Ort richten.", sourceObjectiveStatus = "unverified-source-field" }
quests[79020] = { id = 79020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leer und nichtig", description = "Wir müssen diese monströse Erscheinung Turalyons besiegen.\n\nDie Gegenwart dieser Abartigkeit kann nicht toleriert werden. Wenn wir uns nicht um sie kümmern, könnte sie zerstören, was vom Telogrusriss übrig ist.\n\nIch werde sie mit eigenen Händen vernichten.", sourceObjective = "Besiegt die verderbte Erinnerung an Turalyon im Telogrusriss.", completion = "Es gab einst eine Zeit, in der ich nicht gezögert hätte. In der ich diese Erscheinung mit klarem Herzen erschlagen hätte. Auch wenn sie das Gesicht meines Liebsten trägt.\n\nAber etwas hat sich verändert. Ich habe mich verändert...\n\nGeht. Sprecht mit dem Raumgänger. Er scheint mehr zu wissen als wir.", sourceObjectiveStatus = "unverified-source-field" }
quests[79021] = { id = 79021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strahlende Warnungen", description = "Dann nennt sie sich nun Vorbotin, was? Wie passend.\n\nIch spüre ihre Anwesenheit nicht mehr, aber irrt Euch nicht. Xal'ataths üble Spiele gehen weiter. Und Alleria ist nun ein Spielstein auf ihrem Brett.\n\nSo wie Ihr, Champion des Schicksals.", sourceObjective = "Überbringt die Warnung des Raumgängers Khadgar in Dalaran.", completion = "Xal'atath ist die Vorbotin? Und sie hat den Telogrusriss bereits angegriffen.\n\nDas ist wirklich ernst, {name}. Ich fürchte, wir haben nun keine Zeit mehr für Untersuchungen.\n\nWenn der Raumgänger richtig liegt, finden wir die Antwort im strahlenden Gesang. Wir müssen herausfinden, was das bedeutet.", sourceObjectiveStatus = "unverified-source-field" }
quests[79022] = { id = 79022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein geheimnisvolles Signal", description = "Oberste Sprecherin Brinthe hat einen dringenden Auftrag für Euch, {name}.\n\nSie freut sich, in den kommenden Kriegsanstrengungen helfen zu können, und untersucht ein geheimnisvolles Signal in den Golemwerken der Tiefenschmiede, einer geschlossenen Fertigungsanlage in den schallenden Tiefen.\n\nKönnt Ihr sie dort treffen und sie unterstützen?", sourceObjective = "Trefft Euch mit Brinthe an den Golemwerken der Tiefenschmiede in den Schallenden Tiefen.", completion = "{name}, danke, dass Ihr so schnell gekommen seid. Ich könnte noch einmal Eure Hilfe brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79023] = { id = 79023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleine Freundin, große Pläne", description = "Ich habe ein Notsignal bis zu dieser kleinen Wartungsmaschine verfolgt. Ein seltsamer Fund, doch der wahre Schatz ist die aufgegebene Kriegsgolemfabrik im Südosten.\n\nWenn wir die Produktion von Kriegsgolems wieder aufnehmen können, sind wir in der Lage, etwas zum Krieg beizutragen. Leider ist die Einrichtung von einem Wiederverwertungstrupp der Goblins überrannt worden. Wir müssen herausfinden, ob die Fabrik betriebstüchtig ist.\n\nGlücklicherweise habe ich einen Plan, bei dem unsere kleine Freundin hier eine Rolle spielt. Macht Euch doch einmal miteinander bekannt!", sourceObjective = "Stellt Euch der Wartungsmaschine vor.", progress = "Mit Eurer Hilfe können wir eine Möglichkeit finden, diesen Ort zu säubern.", completion = "Wo wir nun die Formalitäten hinter uns gebracht haben, können uns in die Fabrik schleichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79024] = { id = 79024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufklärung in der Fabrik", description = "ZZ-01-47 müsste sich dort hineinschleichen können, ohne allzu viel Aufmerksamkeit zu erregen.\n\nDoch seid vorsichtig! Diese Goblins nehmen sich alles an Rohmaterialien, was sie kriegen können. Wenn sie unseren Bot entdecken, werden sie keine Gnade kennen.", sourceObjective = "Setzt ZZ-01-47 zur Erkundung der Golemfabrik ein.", progress = "Zet-Zet sollte nicht mehr in Gefahr sein, solange sie den großen Mechs nicht zu nahe kommt.", completion = "Wir haben es also mit einem Mangel an Energie und Materialien sowie einer gefährlichen Anzahl an Goblins zu tun.\n\nWenn ich Poren hätte wie ein Fremdling, würden sie spätestens jetzt Feuchtigkeit absondern. Ist das die korrekte Formulierung? Ich habe beobachtet, wie Eure Haut Feuchtigkeit abgibt. Faszinierend.", sourceObjectiveStatus = "unverified-source-field" }
quests[79025] = { id = 79025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein funktionierender Plan", description = "Wir haben jede Menge zu tun, {name}. Aber ich glaube, dass wir das mit Dagrans Hilfe Schritt für Schritt schaffen können.\n\nGehen wir doch noch einmal durch, was wir bisher alles erfahren haben.", sourceObjective = "Geht den Plan mit Brinthe und Dagran durch.", progress = "Wir gehören zu den hellsten Köpfen in... naja zumindest Gundargaz. Wir kriegen das schon hin.", completion = "Wir müssen die Wasserwerke sichern und die Schattenaderförderstätte einsatzbereit machen, bevor wir in die Fabrik zurückkehren.\n\nAn die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[79026] = { id = 79026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werkstatttermin der Wasserwerke", description = "Übereifrige Kobolde, wütende Elementare und ein kaputtes Kraftwerk. Hier herrscht das reinste Chaos!\n\nSeht Ihr die großen Räder an jeder Seite? Die sollten sich bewegen, tun es aber nicht. Wir müssen sie in Bewegung setzen, wenn wir der Bude wieder Leben einhauchen wollen.", sourceObjective = "Bringt die Wasserwerke wieder ans Laufen.", progress = "Ich frage mich, ob wir diese Technologie verwenden können, um den Steinwerkdamm wiederaufzubauen. Wäre das nicht was?", completion = "Hui, seht mal, wie das läuft!\n\nNur ein Bruchteil von Azeroths Macht genügt für den Schutz.", sourceObjectiveStatus = "unverified-source-field" }
quests[79027] = { id = 79027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementare Zitterpartie", description = "<ZZ-01-47 zuckt hin und her, die Sensoren scannen unaufhörlich. Sie scheint Angst vor diesem Gebiet zu haben, sofern sie überhaupt Angst empfinden kann. Vielleicht beruhigt es sie, wenn wir ein paar Elementare aus dem Weg räumen.>", sourceObjective = "Besiegt Elementare.", progress = "Ich weiß zu schätzen, was Ihr für Zee-Zee tut.\n\nUnd sie wissen es ebenfalls zu schätzen.", completion = "Danke! Ich bin sicher, Zet-Zet weiß das zu schätzen. Wenn wir hier fertig sind, findet Ihr sie an der Schattenaderförderstätte.", sourceObjectiveStatus = "unverified-source-field" }
quests[79028] = { id = 79028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir brauchen mehr Mineralien", description = "Zet-Zet hilft Euch gerne, die Schattenaderförderstätte wieder einsatzbereit zu machen.", sourceObjective = "Macht die Schattenaderförderstätte einsatzbereit.", progress = "<Zet-Zet gibt ein neugieriges Piepsen von sich.>", completion = "<Zet-Zet pfeift erleichtert auf. Anscheinend waren die unterdurchschnittlichen Wartungsstandards hier nicht zufriedenstellend.>", sourceObjectiveStatus = "unverified-source-field" }
quests[79029] = { id = 79029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist Sabotage!", description = "Wir sind zurück und wir sind bereit.\n\nIhr und ZZ-01-47 macht Euch auf den Weg und stiftet Chaos. Sprengt Sachen in die Luft und verursacht Chaos, damit sie aus der Fertigungshalle gelockt werden. Ich werde die Aufregung nutzen, um mich hineinzuschleichen. Kommt so bald wie möglich zu mir, dann haben wir eine Chance, die Anlage wieder zu aktivieren und sie zu vertreiben.\n\nWir müssen nicht alle besiegen. Wenn wir den Anführer der Düsternisverschmolzenen besiegen, der diese Operation überwacht, sollte das ihre Entschlossenheit brechen.\n\nDie düsternisverschmolzenen Lakaien werden verschwinden, wenn keine Münzen mehr klimpern.", sourceObjective = "Haut alles zu Klump, verschafft Euch Zutritt zur Fertigungshalle und bringt die Fabrik wieder ans Laufen.", completion = "Eine Zeitlang war die Sache ziemlich riskant. Aber wenn jemand daraus einen Sieg machen konnte, dann Ihr.\n\nBitte kehrt zum Abgesandten in Dornogal zurück und meldet ihm Euren Sieg. Geht mit meinem Dank und im Wissen, dass die Maschinenflüsterer in Eurer Schuld stehen. Schon wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[79030] = { id = 79030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stimme der Flüsterer", description = "Bitte überbringt Alleria in Dornogal die Nachricht von unserem Sieg. Sicher werden sich unsere Verbündeten freuen, wenn sie hören, was wir für die Kriegsanstrengungen leisten können.", sourceObjective = "Kehrt zu Alleria in Dornogal zurück.", completion = "Das sind fantastische Neuigkeiten, {name}!\n\nDie Kriegsgolems erwachen und marschieren wie in alten Zeiten erneut gegen unsere Feinde.\n\nEuer Beitrag zum Anliegen der Maschinenflüsterer und aller Irdenen wird nicht in Vergessenheit geraten.", sourceObjectiveStatus = "unverified-source-field" }
quests[79074] = { id = 79074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An alle Soldaten!", description = "Das Handwerkerkonsortium hat eine letzte Abmachung mit den Rüstmeistern in der Zuflucht des Gladiators getroffen!\n\nZusätzlich zu der üblichen mächtigen Kampfausrüstung, die sie anbieten, können würdige Kämpfer nun Marken kaufen, die sie in Handwerksaufträgen oder bei eigenen Herstellungsverfahren einsetzen können, um die Ausrüstung zur Verwendung auf Schlachtfeldern und in Arenen zu zertifizieren!\n\nZeigt Calderax diese Broschüre, um zwei kostenlose Trophäen der Eroberung zu erhalten, aufs Haus!\n\n- Rabul", sourceObjective = "Bringt die Broschüre zu Calderax in der Zuflucht des Gladiators von Valdrakken.", completion = "<Calderax murmelt etwas vor sich hin, bevor er zu einer offensichtlich auswendig gelernten Rede ansetzt.>\n\nHier sind Eure Trophäen, wie versprochen. Verwendet sie, wenn Ihr Ausrüstung herstellt oder Handwerksaufträge vergebt, dann wird die Macht der Ausrüstung vergleichbar zu dem sein, was ich anzubieten habe. Perfekt, wenn Ihr nach etwas hochgradig Spezifischem oder nach etwas mit besonderen Verzierungen sucht... und bereit seid, etwas zusätzliche Arbeit reinzustecken.\n\nFragen? Dann meldet Euch beim Handwerkermarkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[79082] = { id = 79082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Superblüte" }
quests[79085] = { id = 79085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Haufen Fisch", description = "<Ein Haufen Fisch. Vielleicht könnte er mit einem Wagen zu Seraphine Saatherz transportiert werden.>", sourceObjective = "Ladet 4 Fische auf den Fischwagenschieber.", sourceObjectiveStatus = "unverified-source-field" }
quests[79089] = { id = 79089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geweihte Reinigung", description = "Unsere Ehrengründe wurden geschändet. Ihre Schönheit wurde zerstört.\n\nEs wird eine größere Anstrengung erfordern, aber ich wäre dankbar für alles, was Ihr tun könnt, um unsere Gründe zu säubern.", sourceObjective = "Richtet die Ehrengründe in Heilsturz her.", progress = "Ich wünschte, Ihr hättet diesen Ort sehen können, bevor die Kobyss hier waren.", completion = "Danke, {name}. Es mag nicht nach viel aussehen, aber das ist einer unserer heiligsten Orte.\n\nWir gedenken hier unserer Toten. Wir... haben viel zu gedenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[79105] = { id = 79105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bresche", description = "So sehr ich Xal'atath auch stellen will, müssen wir zuerst die Zivilisten schützen.\n\nRettet, so viele Ihr könnt, und sagt ihnen, sie sollen sich zum nahen Landeplatz begeben. Ich werde Magier suchen, die alle in Sicherheit teleportieren können.", sourceObjective = "Schickt Zivilisten zu ihrer Sicherheit zur Landestelle.", completion = "Damit ist die erste Gruppe evakuiert. Aber wir sind noch nicht fertig.", sourceObjectiveStatus = "unverified-source-field" }
quests[79106] = { id = 79106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bruch", description = "Folgt mir. Wir werden zusammenarbeiten, um andere zu finden, die gerettet werden müssen.", sourceObjective = "Rettet Dalaran.", progress = "Die Neruber fangen alle, die sie finden können, und wickeln sie in ihre Netze. Bitte befreit so viele wie Ihr könnt, bevor Ihr weiterzieht.", completion = "Wir haben wohl alle gerettet, die wir retten können. Hoffen wir nur, dass die anderen Schurken entkommen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[79107] = { id = 79107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach dem Sturm", description = "Turalyon und Geya'rah bilden bereits die Bodentruppen unserer irdenen Verbündeten aus. Doch wir werden mehr als das brauchen, wir werden die Sturmreiter brauchen. \n\nEtliche fielen bei der Infiltration des Sturmhorts, und wir verloren weitere an die Neruber. Ihr Anführern, Sturmwehr Baelgrim, fand einen heldenhaften Tod.\n\nDie überlebenden Sturmreiter werden an einer Triagestation in der Nähe behandelt. Wir müssen tun, was wir können, damit sie und ihre Krähen bald wieder in der Luft sind. In den kommenden Schlachten werden sie die mächtigsten Waffen der Irdenen sein.", sourceObjective = "Seht nach den Sturmreitern.", completion = "Das mit Shraubendre tut mir leid. Sie wollte mich nur beschützen. Und ich habe gelogen, um sie zu beschützen.\n\nAber habt Ihr wirklich nicht vor, sie wegzuholen? Ihr wollt nur noch mehr Sturmkrähen herbeirufen?", sourceObjectiveStatus = "unverified-source-field" }
quests[79108] = { id = 79108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Samen des Bösen", description = "{class}, einige der Schattenblattpflanzen sind... irgendwie falscher als der Rest. Ich weiß nicht, wie ich das besser beschreiben soll.\n\nMein idiotischer Bruder Tomothy sollte mir bei ihrer Beseitigung helfen, aber er ist nirgendwo zu finden, und ich kann nicht mehr warten.\n\nNatürlich sollen sich diese Dinger nicht vermehren, deswegen sollt Ihr so viele wie möglich von ihnen jäten und ihre Samen entnehmen, die wir dann in heiligem Feuer verbrennen, um diesem Befall ein für alle Mal ein Ende zu machen.", sourceObjective = "Sammelt verderbte Schattenblattsamen.", progress = "Habt Ihr diese Pflanzen gejätet?", completion = "Gute Arbeit beim Jäten dieser Pflanzen. Wenn doch nur mein nichtsnutziger Bruder zur Arbeit erscheinen würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[79109] = { id = 79109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Miral folgen", description = "Tomothys Luchs Miral lässt mich nicht in Ruhe. Keine Ahnung, was das Vieh will, aber normalerweise weicht es meinem Bruder nicht von der Seite. Sie ist eine hervorragende Hofkatze, aber mehr auch nicht. Vielleicht ist ihr bei Tomothy ja langweilig geworden? Keine Ahnung. Könnte sein, dass Tomothy sich irgendwelche Probleme eingehandelt hat.\n\nWürdet Ihr für mich herausfinden, was das Tier will?", sourceObjective = "Findet heraus, was Miral Mordmantel auf dem Herzen hat.", progress = "<Miral sieht Euch an, als würde sie etwas erwarten. Ihr werdet beurteilt.>", completion = "<Miral gibt ein erfreutes Maunzen von sich und schnurrt Euch an.>", sourceObjectiveStatus = "unverified-source-field" }
quests[79110] = { id = 79110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tomothy retten", description = "<Miral sieht Euch erwartungsvoll an, blickt dann in Richtung der Ruinen, schaut erneut zu Euch und dann wieder zu den Ruinen. Ihr erahnt, dass sie dort hingehen will. Vielleicht hat sich ja Tomothy dort verirrt?>", sourceObjective = "Rettet Tomothy Hügelpinne vor der greifenden Dunkelheit.", completion = "Ihr habt meinen idiotischen Bruder vor der Dunkelheit gerettet! Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[79111] = { id = 79111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermisster Luchs" }
quests[79114] = { id = 79114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschönerungsprojekt", description = "Keine schlechte Arbeit für jemanden... von Euresgleichen.\n\nWenn Euch das Atmen am Herzen liegt, würde ich Euch empfehlen, uns weiter zur Hand zu gehen. Es könnte sich für Euch sogar bezahlt machen, solltet Ihr Folge leisten.\n\nDer ehemalige Meister von Rak-Ush hat es den Hirschpanzern erlaubt, Amok zu laufen, ist dann abgehauen und hat die Grotte dem Verfall überlassen. Im Laufe der Zeit haben sich invasive Pflanzen in den alten Hirschpanzergrotten ausgebreitet.\n\nFindet einen Weg, sie zu beseitigen. Wie Ihr das anstellt, ist mir egal.", sourceObjective = "Beseitigt die Wuchernden Pflanzen in der Hirschpanzergrotte.", progress = "Es wäre nicht sehr weise, zu mir zurückzukehren, bevor Euer Auftrag erledigt ist.", completion = "Hm. Das sollte reichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79115] = { id = 79115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berater vom Fach", description = "Ihr allein reicht nicht mehr aus. Wir benötigen zusätzliche Hilfe, und die Kieferkriecher und Fädlinge müssen ebenfalls überwacht werden.\n\nDie Niffensiedlung Mmarl ist nicht weit entfernt. In der Vergangenheit sind Versuche, Einberufungen zu erzwingen, jedoch gescheitert. Neruber sind in der Stadt nun verboten. Wir brauchen jemanden, der als unser Sprachrohr fungiert.\n\nGeht und verhandelt mit den Ratten. Und kommt mit fähigen Arbeitern zurück.", sourceObjective = "Sprecht mit dem Anführer in Mmarl über die Rekrutierung von Schwarmarbeitern.", completion = "Die Neruber wollen wieder unsere Hilfe? Das würde ich mir gerne anhören...", sourceObjectiveStatus = "unverified-source-field" }
quests[79116] = { id = 79116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auge um Auge um Auge um..." }
quests[79117] = { id = 79117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kluge, junge Niffen", description = "Ihr braucht Schwarmarbeiter, wie?\n\nLetztes Mal, als die Neruber unsere Hilfe gebraucht haben, wollten sie uns dazu zwingen. Sie sind schreckliche Verhandlungspartner! Alles, was wir wollten, war eine kleine Gegenleistung.\n\nWir haben mehrere Arachnologen, doch die meisten von ihnen sind damit beschäftigt, die Gleiter auf Abstand zu halten. Ich bin mir sicher, dass sie sich die Gelegenheit nicht entgehen lassen wollen, ein paar Schwarmbestien aus der Nähe zu studieren.\n\nWenn Ihr ihnen etwas Arbeit abnehmt, nehmen sie das Angebot vielleicht sogar an.", sourceObjective = "Findet 6 Arachnologen der Niffen außerhalb von Mmarl, die sich Rak-Ush anschließen.", completion = "Seht Ihr? Alles, was wir wollten, war eine Kleinigkeit im Gegenzug.", sourceObjectiveStatus = "unverified-source-field" }
quests[79118] = { id = 79118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rak-Ush unter neuer Führung", description = "Nun, Ihr habt Eure Schwarmarbeiter.\n\nWas macht Ihr noch hier? Na los, Ihr braucht meine Erlaubnis nicht.\n\nAber stellt sicher, dass die Neruber sie fair behandeln.", sourceObjective = "Kehrt zu Vix'aron in Rak-Ush zurück.", completion = "Ausgezeichnet.", sourceObjectiveStatus = "unverified-source-field" }
quests[79119] = { id = 79119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es ist nicht leicht, ein Käfer zu sein!", description = "Anub'azal hat seine Befehle ausgegeben! Wir haben nun die Kontrolle über Rak-Ush! Doch Vix'aron musste ja stattdessen ausflippen und unsere Scheune zerstören.\n\nDa dieser Dummkopf sich weigert, Befehle zu befolgen, liegt es nun an Euch, Überkrabbler. Vielleicht bringen wir Euch dann auch nicht um fürs Lauschen. Und vielleicht erwartet Euch ja sogar eine Belohnung.\n\nGeht. Wir sollen die Hirschpanzergrotte wieder herrichten und sie mit Schwarmbestien füllen.", sourceObjective = "Säubert die Scheune in Rak-Ush.", progress = "Wir brauchen diese Scheune in betriebsfähigem Zustand!", completion = "Überraschenderweise habt Ihr Euch als nützlich erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79120] = { id = 79120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Käfer im Heuhaufen", description = "Im Gebiet um Rak-Ush befinden sich wilde Hirschpanzer.\n\nDiese Geruchsgranate sollte ausreichen, um die Tiere zu betäuben und die Niffen über ihre Position zu informieren.\n\nSobald sie betäubt sind, wird eine der Ratten sie zurück in ihre Höhle bringen.\n\nFangt sie und bringt sie zurück. Wir warten.", sourceObjective = "Fangt 6 wilde Hirschpanzer und bringt sie zurück nach Rak-Ush.", completion = "Ausgezeichnete Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[79121] = { id = 79121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Käferwissen", description = "Oh, tut mir leid, aber dachtet Ihr etwa, dass das eine einmalige Angelegenheit war? Wenn dem so ist, zeigt Vix'aron Euch nur zu gerne, wo \"die Tür\" ist, sozusagen. Die Hirschpanzer bedürfen regelmäßiger Pflege. Essen. Wasser. All so was.\n\nSo ungern ich es auch eingestehe, aber die Niffen sind deutlich besser darin, sich um die Schwarmbestien zu kümmern, als Vix'aron und ich.\n\nFalls dies als Erklärung nicht gereicht haben sollte, können sie Euch über Eure Pflichten aufklären.", sourceObjective = "Sprecht mit Aromash und kümmert Euch um die Hirschpanzer in Rak-Ush.", progress = "Kommt nicht zurück, bevor die Niffen Euch unterwiesen haben.", completion = "Ich hoffe mal, dass das nicht zu kompliziert für Euch war.", sourceObjectiveStatus = "unverified-source-field" }
quests[79122] = { id = 79122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skarabäen spähen", description = "Die Hirschpanzer sind für Anub'azals Kriegskampagne von äußerster Wichtigkeit. Wir haben einen ausgeprägten Geruchssinn, doch nur die Hirschpanzer sind in der Lage, wertvolle Kahetitrüffel aufzuspüren.\n\nSie sind eine wichtige Zutat verschiedener... explosiver Elixiere, sozusagen. Falls Ihr weitere Einzelheiten darüber erfahren wollt, kann Aromash Euch darüber in Kenntnis setzen.", sourceObjective = "Nutzt einen Hirschpanzer von Rak-Ush, um 5 Kahetitrüffel zu finden.", progress = "Wir brauchen eine große Menge an Trüffeln, um sicherzugehen, dass wir gut vorbereitet sind.", completion = "Das war alles, was wir von Euch gebraucht haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[79123] = { id = 79123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbefristete Anstellung", description = "Rak-Ush sieht langsam wie ein betriebsfähiger Schwarmhof aus.\n\nVix'aron und ich machen uns wirklich gut bei der Delegierung von Aufgaben. Ihr werdet weiterhin den Niffen helfen. Im Gegenzug dürft Ihr einen Teil der Reichtümer, die die Schwarmbestien produzieren, einbehalten.\n\nSaffrin hat genauere Pläne dazu, was die Entwicklung des Schwarmhofs angeht. Sprecht mit ihm. Ich habe Euch nichts weiter zu sagen.", sourceObjective = "Sprecht mit Saffrin in Rak-Ush.", completion = "Diese Schwarmbestien versorgen sich nicht selbst!", sourceObjectiveStatus = "unverified-source-field" }
quests[79124] = { id = 79124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leiter des Südlichen Sturms", description = "Ich sage Euch, was ich Baelgrim sagte, als ich zuletzt mit ihm sprach. Die Bindung der Sturmkrähen ist ein Fehler. Diese Kreaturen sind so klug wie viele Irdenen. Ich würde sogar sagen, manche sind klüger.\n\nDoch... Lufsela scheint anders zu sein. Wenn ihre Sturmkrähe ihr freiwillig folgt, dann würden vielleicht auch andere diese Entscheidung treffen, die sie beschwört.\n\nUm die Krähen zu beschwören, brauchen wir Baelgrims Leiter. Er ist hier irgendwo verstaut. Seht Euch um und fragt vielleicht diese Pilger, ob sie ihn gesehen haben.", sourceObjective = "Findet den Leiter des Südlichen Sturms.", progress = "Habt Ihr die Leitung gefunden?", completion = "Olbarig war nicht nur selbst einst Sturmreiter, sondern lange Jahre auch Baelgrims rechte Hand als Sturmwache. Offenbar trennten sie sich im Streit über die Krähen.\n\nOlbarig sagt, der Leiter fungiert wie ein Leuchtfeuer. Wenn die Sturmkrähen von Himmelswall gewillt sind, werden sie so durch den Sturm geleitet. Er meint offenbar auch, dass ich es sein sollte, die den Leiter einsetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[79125] = { id = 79125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kalimdorpokal beginnt", description = "<Himmelsreiter/Himmelsreiterin>! Lord Andestrasz hat die Dracheninseln verlassen und ist zu Besuch in Sturmwind. Er sucht nach fähigen Himmelsreitern wie Euch zur Teilnahme an neuen Rennen!", sourceObjective = "Sucht Lord Andestrasz in Sturmwind auf.", completion = "Danke für den Besuch, Himmelsreiter!", sourceObjectiveStatus = "unverified-source-field" }
quests[79126] = { id = 79126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kalimdorpokal beginnt", description = "<Himmelsreiter/Himmelsreiterin>! Lord Andestrasz hat die Dracheninseln verlassen und ist zu Besuch in Orgrimmar. Er sucht nach fähigen Himmelsreitern wie Euch zur Teilnahme an neuen Rennen!", sourceObjective = "Sucht Lord Andestrasz in Orgrimmar auf.", completion = "Danke für den Besuch, Himmelsreiter!", sourceObjectiveStatus = "unverified-source-field" }
quests[79127] = { id = 79127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Scherbenweltpokal beginnt", description = "<Himmelsreiter/Himmelsreiterin>! Lord Andestrasz hat die Dracheninseln verlassen und ist zu Besuch in Sturmwind. Er sucht nach fähigen Himmelsreitern wie Euch zur Teilnahme an neuen Rennen!", sourceObjective = "Sucht Lord Andestrasz in Sturmwind auf.", completion = "Danke für Euren Besuch, Drachenreiter!", sourceObjectiveStatus = "unverified-source-field" }
quests[79128] = { id = 79128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Scherbenweltpokal beginnt", description = "<Himmelsreiter/Himmelsreiterin>! Lord Andestrasz hat die Dracheninseln verlassen und ist zu Besuch in Orgrimmar. Er sucht nach fähigen Himmelsreitern wie Euch zur Teilnahme an neuen Rennen!", sourceObjective = "Sucht Lord Andestrasz in Orgrimmar auf.", completion = "Danke für Euren Besuch, Drachenreiter!", sourceObjectiveStatus = "unverified-source-field" }
quests[79129] = { id = 79129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konferenz der Krähen", description = "Jetzt, wo wir die Leitung voll aufgeladen haben, ist es wohl an der Zeit, dass wir uns mit allen auf dem Gipfel treffen. \n\nThrall hat mir erklärt, was mich erwartet, aber er hat auch gesagt, dass ich meinen Gefühlen und Instinkten vertrauen muss, wenn ich die Sturmkrähen beschwören will.\n\nEin Irdener, der seinen Gefühlen und Instinkten vertraut. Das ist... eine Herausforderung.\n\nIhr werdet mir doch helfen, oder? Ich bin keine Kämpferin, und da oben sieht es gefährlich aus. \n\nWenn mir etwas zustößt, sorgt dafür, dass Shraubendre es sicher heraus schafft. Bitte.", sourceObjective = "Beschützt das Beschwörungsritual.", completion = "Gut gemacht. Wie es scheint, sind die Krähen von Himmelswall nicht bloß dem Ruf gefolgt. \n\nSie haben den Kontakt zu uns gesucht, und sie haben ihre Reiter für diese Generation selbst ausgewählt.\n\nIch fühle mich geehrt, bei diesem Ritual mitgewirkt zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[79130] = { id = 79130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Strecken des Nordendpokals", description = "Es ist an der Zeit, Euren Mut wieder auf die Probe zu stellen.\n\nMeine Bronzekollegen sind nach Nordend gereist, um weitere Herausforderungen bereitzustellen. Wir würden gerne sehen, ob mutige Himmelsreiter alle Strecken abschließen können!\n\nSeid Ihr bereit?", sourceObjective = "Fliegt durch die Strecken des Nordendpokals.", completion = "Ihr seid Euren Drachenreiterkollegen voraus! Wenn Ihr es noch nicht getan habt, könnt Ihr Eure Zeiten beim Nordendpokal verbessern und Euch die Farben der Reiter von Azeroth verdienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79131] = { id = 79131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Nordendpokal beginnt", description = "<Himmelsreiter/Himmelsreiterin>! Ihr habt Lord Andestrasz gerade verpasst. Er ist auf der Suche nach fähigen Himmelsreitern wie Euch, die sich in den neuen Rennen messen!", sourceObjective = "Sucht Lord Andestrasz in Valdrakken auf.", completion = "Danke für Euren Besuch, Drachenreiter!", sourceObjectiveStatus = "unverified-source-field" }
quests[79132] = { id = 79132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Nordendpokal beginnt", description = "<Himmelsreiter/Himmelsreiterin>! Lord Andestrasz hat die Dracheninseln verlassen und ist zu Besuch in Sturmwind. Er sucht nach fähigen Himmelsreitern wie Euch zur Teilnahme an neuen Rennen!", sourceObjective = "Sucht Lord Andestrasz in Sturmwind auf.", completion = "Danke für Euren Besuch, Drachenreiter!", sourceObjectiveStatus = "unverified-source-field" }
quests[79133] = { id = 79133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Nordendpokal beginnt", description = "<Himmelsreiter/Himmelsreiterin>! Lord Andestrasz hat die Dracheninseln verlassen und ist zu Besuch in Orgrimmar. Er sucht nach fähigen Himmelsreitern wie Euch zur Teilnahme an neuen Rennen!", sourceObjective = "Sucht Lord Andestrasz in Orgrimmar auf.", completion = "Danke für Euren Besuch, Drachenreiter!", sourceObjectiveStatus = "unverified-source-field" }
quests[79134] = { id = 79134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frühlingserwachen", description = "Die Einwohner von Goldhain haben gemeldet, dass ihre Festivitäten in letzter Zeit häufig gestört wurden. Irgendetwas von einer Plage wütender... Enten? Vielleicht könntet Ihr Euch um dieses Problem kümmern.", sourceObjective = "Sprecht mit Zinnia Brooks in Goldhain im Wald von Elwynn.", completion = "Ja! Ja, ich glaube, ich habe genau die richtige Aufgabe für Euch...", sourceObjectiveStatus = "unverified-source-field" }
quests[79135] = { id = 79135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quakende Maßnahmen", description = "Diese verflixten Enten! Wärt Ihr wohl bereit, sie noch einmal zu vertreiben? Ich kann mein goldenes Ei nicht unbewacht lassen!", sourceObjective = "Verschreckt 10 Enten mithilfe des Horns des Hupens.", progress = "Habt Ihr diese Enten schon genug verscheucht?", completion = "Oh, da bin ich aber erleichtert. Diese Enten treiben mich in den Wahnsinn!", sourceObjectiveStatus = "unverified-source-field" }
quests[79136] = { id = 79136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frühlingserwachen", description = "Die Einwohner von Klingenhügel haben gemeldet, dass ihre Festivitäten in letzter Zeit ausgerechnet durch eine Entenplage gestört wurden. Vielleicht könntet Ihr Euch um dieses Problem kümmern.", sourceObjective = "Sprecht mit Sylnaria Seherflamme in Klingenhügel.", completion = "Ja! Ja, ich glaube, ich habe genau die richtige Aufgabe für Euch...", sourceObjectiveStatus = "unverified-source-field" }
quests[79137] = { id = 79137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Mauer zwischen uns", description = "Ich weiß, das war nicht Euer Kampf, {name}. Aber ich danke Euch für Eure Hilfe. Mit der Unterstützung der Allianz wurde Lordaeron geläutert, und dieser Gefallen wurde nun beglichen.\n\nIch glaube nicht, dass ich auf Frieden hoffen kann. Stattdessen werde ich hoffen, dass diese Mühen zumindest zu mehr Verständnis geführt haben, was die Nöte der Gilneer und der Verlassenen angeht.\n\nTreffen wir uns mit Lilian in Lohenscheit. Diese Feier ist nicht für uns gedacht.", sourceObjective = "Sprecht mit Lilian und Calia in Lohenscheit.", completion = "Nicht meine Vorstellung einer normalen Bitte eines Freundes, aber ich bin dem Töten weiterer Kreuzzügler nie abgeneigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[79139] = { id = 79139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allein in der Dunkelheit", description = "Mein Volk glaubt nicht, dass das Schwarze Blut eine Bedrohung für unsere Welt darstellt. Schließlich hat es lange Zeit geschlummert. Warum sollte sich das jetzt ändern?\n\nAber die Welt verändert sich schneller, als meinem Volk bewusst ist. Die Entscheidung der Neruber, das Blut für ihre eigenen Zwecke zu nutzen, ist der Beweis dafür.\n\nDie Neruber kontrollieren nicht weit von hier einen Wachturm. Die Überlebenden der Grube können nicht allzu weit gekommen sein. Wir sollten sofort die Verfolgung aufnehmen.", sourceObjective = "Untersucht das Auge von Ansurek.", completion = "<Die Augen des bizarren Wesens sind weiterhin felsenfest auf Euch gerichtet. Es schiebt etwas in Eure Richtung: eine Schriftrolle mit einem dicken violetten Wachssiegel.>", sourceObjectiveStatus = "unverified-source-field" }
quests[79140] = { id = 79140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldziegel", description = "Darauf sollen wir uns verlassen, um Xal'atath zu besiegen? Die Freien definieren sich durch ihre Fahnenflucht. Und die Eingeschworenen sind ziemliche Weichlinge, obwohl sie aus Stein sind. Das Stadtleben hat ihnen nicht gutgetan. \n\nWir haben eine Menge Arbeit vor uns.\n\nGeht da runter und gebt diesen Irdenen einen Vorgeschmack darauf, wie es sich anfühlt, einer echten Bedrohung gegenüberzustehen. Versucht, keinen \"offline\" zu hauen, aber eine Verstümmelung hier oder da würde eine starke Botschaft an den Rest senden.", sourceObjective = "Tragt Übungskämpfe mit undisziplinierten irdenen Rekruten aus.", progress = "Seid nicht zu nachsichtig mit ihnen. Sie sind immerhin aus Stein.", completion = "Ihr habt dort unten das Feuer entzündet, und wir werden es weiter anfachen. \n\nGeht nun in dem Wissen, dass Ihr die Irdenen auf den Weg zum Ruhm gebracht habt. Die Neruber werden nicht wissen, wie ihnen geschieht!", sourceObjectiveStatus = "unverified-source-field" }
quests[79145] = { id = 79145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Metalle und Steine", description = "Bei manchen dieser Rekruten hapert es an der Disziplin, aber die meisten haben eine hohe Arbeitsmoral. Sie brauchen nur das richtige Training und die richtige Ausrüstung, um voranzukommen.\n\nIrdene Waffen- und Rüstungsschmiede arbeiten rund um die Uhr, um diese Armee im Aufbau auszustatten. Trotzdem können wir Hilfe gebrauchen, um die neuen Waffen zu den Rekruten zu bekommen.", sourceObjective = "Rüstet irdene Rekruten für den Kampf aus.", progress = "Meldet Euch bei Verteidigerin Jaelaana. Sie leitet die Waffenausgabe, obwohl sie recht streng sein kann. Gebt Acht, dass sie nicht zu viele zum Nahkampftraining schickt.", completion = "Jetzt sehen sie fast wie eine echte Armee aus. Wir trainieren sie weiter, aber Ihr habt gewiss Wichtigeres zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[79146] = { id = 79146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bodentrommler", description = "Die Krähen und ihre ausgewählten Reiter werden Zeit brauchen, um eine Verbindung zueinander aufzubauen. \n\nVielleicht solltet Ihr diese Zeit nutzen, um nach unseren anderen Schülern zu sehen. \n\nDie Sturmreiter sind die traditionelle Armee der Irdenen, aber viele der Freien und Eingeschworenen haben sich bereit erklärt, an unserer Seite zu kämpfen, weil sie bei der Wiederherstellung ihrer Maschinen helfen wollen.\n\nAdelgonn, Geya'rah und Turalyon sind mit ihrer Ausbildung beschäftigt. Geht und seht nach, ob sie Hilfe brauchen.", sourceObjective = "Trefft Adelgonn, Geya'rah und Turalyon.", completion = "So rette mich doch jemand vor all diesem Gezänk! Allianz hier, Horde da... \n\nSo etwas ist mir in meinen Tausenden von Jahren noch nie begegnet, nicht einmal bei den Freien und den Eingeschworenen. Wenn sie nur die Hälfte der Energie, die sie für ihr Gehabe aufwenden, in die Ausbildung stecken würden, wäre unsere Aufgabe schon erledigt.\n\nSchaut, wie Ihr meinem Volk helfen könnt. Sie brauchen einen echten Mentor, wenn wir für die nächste nerubische Offensive bereit sein wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79147] = { id = 79147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flugtraining für Anfänger", description = "Da nun alle Rekruten anwesend sind, wird es höchste Zeit, loszufliegen. Verstanden? Höchste...? Nein?\n\nAlso gut. Wir zeigen diesen Anfängern wie's geht. Wir beginnen mit den Grundlagen des Manövrierens in der Luft. Dazu simulieren wir möglichst genau die Präzisionsfliegerei, wie sie unter der Erde nötig wird.\n\nAnschließend schauen wir, was diese Krähen wirklich können. Und ich glaube, dass Thrall und Lufsela etwas ganz Besonderes vorbereiten.", sourceObjective = "Helft Kurdran, mit den Rekruten Flugmanöver zu trainieren.", progress = "Lasst uns ein Vorbild für diese neuen Reiter sein. Führt sie so schnell wie möglich über die Strecke.", completion = "Da sind sie! Rekruten aus Stein, die auf dem Rücken von Vögeln aus Blitzen in die Lüfte aufsteigen. Da sieht man mal wieder, dass Kurdran wirklich alles zum Fliegen bringt!\n\nAber wir sind noch nicht fertig.", sourceObjectiveStatus = "unverified-source-field" }
quests[79148] = { id = 79148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nibelgazraffinerie", description = "Schnell! Elementare haben die Nibelgazmine überrannt und die Raffineriearbeiter sind dort unten mit ihnen gefangen.\n\nIch mache mir besonders Sorgen um meinen Partner Munderut. Sein Gedächtnis ist in letzter Zeit nicht das beste. Wenn Ihr <ein Freund/eine Freundin> seid, rettet Ihr ihn und die Raffineriearbeiter.\n\nHier, nehmt diesen heilenden Ton. Er hilft nur ein wenig, aber das sollte ausreichen, damit die Verletzten es zurück schaffen. Ich wünschte, wir hätten einen Verjüngungskristall, aber den gibt es wohl nur in Legenden.", sourceObjective = "Rettet 6 Raffineriearbeiter und sucht nach Munderut.", completion = "Die Arbeiter hier haben mir gesagt, dass Ihr ihnen bei der Flucht aus der Raffinerie geholfen habt. Aufgabe abgeschlossen!\n\nIch nehme diesen Ton wieder an mich. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[79149] = { id = 79149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Randale in der Raffinerie", description = "Katastrophe! Oh, das ist schrecklich. Schrecklich! Diese verfluchten Abraumelementare halten meine Raffineriearbeiter davon ab, ihre Arbeit zu erledigen.\n\nDie Pflicht verlangt, dass wir unsere Arbeit fortsetzen. Diese Verzögerungen werden nicht geduldet. Ihr seht relativ fähig aus. Also los, geht da runter und vernichtet Elementare. Die Produktion darf nicht verlangsamt werden!", sourceObjective = "Tötet 10 tobende Elementare.", progress = "Und? Habt Ihr sie vernichtet? Meine Arbeiter müssen sofort wieder an die Arbeit!", completion = "Was für eine schreckliche Produktionsverzögerung. Die Minenarbeiter werden doppelt so hart arbeiten müssen, um die verlorene Zeit aufzuholen, fürchte ich.\n\nEs ist gut, dass Ihr rechtzeitig gekommen seid. Diese Elementare sind eine Bedrohung. Eine schreckliche Bedrohung!", sourceObjectiveStatus = "unverified-source-field" }
quests[79150] = { id = 79150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mimen im Proszenium", description = "Als ich die Stücke der Freien nach Dornogal bringen wollte, hatte ich keine Ahnung, worauf ich mich da einließ. Oder dass meine \"Hilfe\" zum Problem werden würde.\n\nMein alter Freund Brokfor stört uns immer mit seinem Perfektionismus! Wenn wir versuchen, Kulissen zu bauen, hält alle auf, um jeden einzelnen Nagel zu inspizieren. Wir versuchen zu streichen und er beschwert sich, dass die Farben nicht perfekt harmonieren... Ihr versteht, was ich meine.\n\nIch glaube Brokfor braucht sein eigenes Projekt. Vielleicht... könnte er das Proszenium aufräumen? Bittet ihn um Hilfe, damit er beschäftigt ist.", sourceObjective = "Helft dem Architekten Brokfor, das Proszenium aufzuräumen.", progress = "Habt Ihr Brokfor beim Aufräumen geholfen?", completion = "Ausgezeichnet! Jetzt können wir unsere Aufgaben erledigen, ohne dass sein Perfektionismus uns in die Quere kommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[79151] = { id = 79151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anliegen einer Waise", description = "Wow, Ihr seht wirklich stark aus. Könntet Ihr mir vielleicht helfen?\n\nMeine Eltern wurden von den gemeinen Kobyss getötet. Als ich hierhin geflohen bin, musste ich meinen geliebten Teddybären zurücklassen.\n\nKönntet Ihr ihn für mich holen?", sourceObjective = "Holt Alyzas vielgeliebten Teddybär aus dem Lauernden Strudel in Heilsturz.", progress = "Ich werde dafür sorgen, dass die Kobyss es bereuen, jemals einen Fuß in dieses Land gesetzt zu haben.", completion = "Gut, gut. Ich schätze, Ihr könnt gern helfen kommen.\n\nIhr seht wirklich groß und stark aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[79152] = { id = 79152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strudel schlagen", description = "Die Kobyss sind... etwas größer, als ich gedacht hatte, und ich habe möglicherweise, also... Ihr versteht doch, was ich meine? Also möglicherweise habe ich mehr Schwierigkeiten mit ihnen, als ich mir ausgemalt habe.\n\nTötet jede blöde Fischfratze, die Ihr seht.", sourceObjective = "Tötet 10 Kobyss im Lauernden Strudel in Heilsturz.", progress = "Ja, lasst sie bluten. Lasst sie bezahlen!", completion = "Ihr habt viele von ihnen getötet.\n\nIch hätte auch nichts dagegen, wenn Ihr noch mehr töten würdet. Nur so am Rande.", sourceObjectiveStatus = "unverified-source-field" }
quests[79153] = { id = 79153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wehe den Besiegten", description = "Ah, die Zeit ist gekommen.\n\nTötet ihren Anführer. Salzt seine Knochen, reißt seinen Kopf ab und lacht, während sein Stamm zerfällt!\n\nScharfschuppe hat keine Ahnung, dass er bald seinen letzten Atemzug machen wird. \n\nDämliche Fischvisage.", sourceObjective = "Tötet Scharfschuppe den Verschlinger im Lauernden Strudel in Heilsturz und bringt seinen Kopf zurück.", progress = "Sein Schädel würde sich doch gut als Tasse eignen, nicht wahr? Oder als Zierstück auf dem Kaminsims?", completion = "Oh. Dieser Kopf ist ekliger, als ich erwartet hatte. Ihr könnt ihn behalten.\n\nIhr wart viel nützlicher, als ich anfangs erwartet habe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[79154] = { id = 79154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein letztes Lebwohl", description = "Schön, Eltern gerächt, Fische getötet, mehr Fische getötet, den größten Fisch getötet.\n\nWar ein guter Tag.\n\nIch glaube, ich geh mal was verbrennen.", sourceObjective = "Helft Alyza beim Abschiednehmen im Lauernden Strudel in Heilsturz.", completion = "Danke, {name}. Ich werde bei Generalin Stahlstoß ein gutes Wort für Euch einlegen. Ich kenne sie ganz gut.\n\nAlso, ich hab sie einmal getroffen.\n\nGenauer gesagt, ich hab sie auf der Straße gesehen.\n\nAber ich habe wirklich überlegt, sie anzusprechen, das ist also quasi dasselbe.", sourceObjectiveStatus = "unverified-source-field" }
quests[79156] = { id = 79156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Edikte", description = "Merrix und Adelgonn wollen bestimmt wissen, wie es läuft. Auf dem Weg hierher habe ich gehört, dass sie zum Proszenium kommen, um uns offiziell auf den Krieg einzuschwören. Meldet ihnen, dass die Sturmreiter bereit sind.\n\nIch brauche noch einen Moment mit Zarein. Aber wir kommen bald und bringen den Geist Baelgrims mit.", sourceObjective = "Meldet Euch bei Merrix und Adelgonn", completion = "Titanen! Was haben sie getan?", sourceObjectiveStatus = "unverified-source-field" }
quests[79157] = { id = 79157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Titanische Sicherung", description = "Die Titanen haben also ihre uralten Maschinen gegen ihre ungehorsamen Kinder geschickt.\n\nWollten unsere Schöpfer, dass wir den Kernweg schützen und alles andere opfern? Sogar Azeroth selbst? Sollen wir über eine Straße zum toten Herzen der Welt wachen, auf der niemand reist?\n\nNein. Heute sind wir alle frei und kämpfen für unsere Freiheit. Für Azeroth!", sourceObjective = "Besiegt das kolossale Titanenkonstrukt.", progress = "Niemand auf dieser Insel wird sicher sein, bis wir uns um dieses Titanenkonstrukt gekümmert haben. Los!", completion = "Es war eine Feuerprobe, aber Ihr habt bewiesen, dass die Irdenen der Insel von Dorn für den kommenden Krieg gerüstet sind. Wo früher Zwietracht herrschte, besteht jetzt Einigkeit. Sie sind keine Eingeschworenen oder Freien mehr. Sie sind vereint, genau wie wir es sein sollten, im Kampf gegen die Dunkelheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[79158] = { id = 79158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saaten der Rettung", description = "Die einst gehorsamen Erntebots laufen Amok und verursachen Chaos auf unseren Feldern.\n\nDer Erfolg unserer Gemeinde hängt davon ab, dass wir unsere Samen anpflanzen, aber der Großteil der Samen ist in den Händen dieser Ernter!\n\nKönnt Ihr Euch zu den Feldern begeben, die ungehorsamen Maschinen eliminieren, die Samen einsammeln und dann pflanzen?", sourceObjective = "Beschafft Erntesaat und pflanzt 8 Samenkörner in saatfertigen Boden ein.", progress = "Habt Ihr die Saat ausgebracht?", completion = "Ihr habt uns wirklich einen großen Dienst erwiesen! Das Einpflanzen dieser Samen verschafft uns wertvolle Zeit, bis die Erntebots repariert sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[79159] = { id = 79159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pflichtvernachlässigung", description = "Einen Augenblick bitte.\n\nEiner meiner Leutnants, Shinda Glaubenspike, hat sich nicht am ersten Feuer gemeldet. Das mag für Euch nicht wie ein großes Problem aussehen, aber die Arathi können in Heilsturz nur überleben, weil wir Befehle befolgen und für unsere Geschwister einstehen.\n\nIch bin nicht grausam und will in dieser furchtbaren Umgebung keinen Mann für seine Schwächen bestrafen. Könntet Ihr ihn finden und zurückholen?\n\nNehmt Euch alle Zeit, die Ihr braucht.", sourceObjective = "Findet Shinda Glaubenspike in Mereldar in Heilsturz.", progress = "Bestimmt hat Dämmerschnell Euch geschickt.\n\nMeine kleine Ruhepause ist damit wohl vorbei.", completion = "Ihr sprecht meine Sprache, {name}. Pläne geben mir Struktur und ein Ziel, das ich erreichen muss.\n\nLasst mich darüber nachdenken, wie ich mich optimal entspannen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[79160] = { id = 79160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angeln ist gut für die Seele", description = "Als ich klein war, ging ich mit meiner Mutter immer an den örtlichen Teich angeln. Auf die Fische kam es mir dabei nicht an, denn meine Mutter war für ihre schlechten Kochkünste berüchtigt. Wichtig waren mir die Ruhe und die miteinander verbrachte Zeit.\n\nVielleicht kann ich einen Teil dieses Seelenfriedens hier wiederfinden. Südlich von Mereldar gibt es einen Angelplatz. Wir sehen uns dort!", sourceObjective = "Trefft Shinda am Angelloch.", progress = "Vielleicht kann ich ja beim Angeln Frieden finden.", completion = "Ich wünschte, wir hätten angeln können. Aber der heutige Tag hat mir bestätigt, dass ich eine wertvolle Wahrheit neu gelernt habe.\n\nWenn ich mein Schwert niederlege, müssen diese Kinder es aufheben, wenn sie hier überleben wollen. Sie kennen keinen anderen Ort als dieses Land.\n\nSie werden unsere Heimat sehen. Sie müssen unsere Heimat sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79162] = { id = 79162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgebrannt", description = "Bitte kehrt zu Kommandant Dämmerschnell zurück und richtet meine aufrichtige Entschuldigung für meine Abwesenheit aus. Nach meiner Schicht melde ich mich, um die Strafe für meine Verfehlungen anzunehmen.", sourceObjective = "Kehrt zu Endiri Dämmerschnell in Mereldar zurück.", completion = "Ich werde keine Strafe für seine Abwesenheit verhängen. Ich bin einfach nur froh, dass Ihr ihn unterstützt habt, als ich nicht konnte.\n\nWir leben in Zeiten der Prophezeiung, {name}. Es ist ein Fluch, den ich niemandem aufbürden möchte. Wir müssen tun, was nötig ist, um heutzutage zu überleben.", sourceObjectiveStatus = "unverified-source-field" }
quests[79165] = { id = 79165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Moment zum Ausruhen", description = "Gut, Ihr seid beide hier. \n\nIch muss Euch um einen Gefallen bitten. \n\nFaerin ist davongelaufen. Ich denke, Ihr und Euer... zausiger Freund hier könntet helfen, sie zu finden.\n\nSie muss irgendwo in Lichtschanze sein.", sourceObjective = "Findet Faerin in der Nähe von Lichtschanze.", completion = "<Anduin kaut gedankenverloren auf der Lippe.>", sourceObjectiveStatus = "unverified-source-field" }
quests[79166] = { id = 79166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlorene Gegenstände", description = "Es gab eine Zeit, in der ich gewusst hätte, mit welchen Worten ich ihr helfen könnte.\n\nDoch nun... habe ich sie wie alles andere vergessen.\n\n<Anduin seufzt.>\n\nWir müssen doch irgendetwas tun können. Ihr alter Lampenanzündergefährte, Andari... hat doch bestimmt so einen Zunderkasten, oder? Für Beerdigungsriten scheinen die wichtig zu sein.\n\nIch werde Faerin zurück nach Mereldar begleiten. Dort treffen wir uns. Wenn Ihr glaubt, dass sich Andaris verlorene Sachen vielleicht noch finden lassen... könntet Ihr mal nachsehen?", sourceObjective = "Sammelt 8 Stück verlorene persönliche Habe von Gegnern im Schüttergrund.", progress = "Wir haben keine Zeit zu trauern. Nicht, wenn wir noch kämpfen müssen. Wer Zeit zu trauern hat, hat auch Zeit zu trainieren.\n\nDamit wir nicht noch mehr Leute verlieren.", completion = "Ihr habt ihre Sachen gefunden? In dieser absoluten Dunkelheit?\n\nDanke.\n\nUnd das, das ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[79167] = { id = 79167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschaffung aus der Menge", description = "Schachzug des Lichts ist ein altes und ehrwürdiges Spiel. Es gibt einen Grund, warum es so viele Arathi spielen!\n\nMan lernt dabei viel über Strategie. Und man erfährt viel über seine Gegner.\n\n<Faerin atmet plötzlich erleichtert aus.>\n\nAber uns fehlen noch ein paar Spielfiguren.\n\nManchmal leihen uns die Leute in Mereldar welche. Könntet Ihr die mal fragen?", sourceObjective = "Sammelt 4 Spielteile von den Arathi in Mereldar.", progress = "Die Regeln sind ein wenig langatmig, aber vertraut mir... Das ist es wert!", completion = "Wir... waren wohl etwas voreilig.", sourceObjectiveStatus = "unverified-source-field" }
quests[79168] = { id = 79168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schachzug des Lichts", description = "Schon in Ordnung! Die restlichen Regeln gehen wir später durch!\n\nDer Entscheidungskampf macht sowieso am meisten Spaß!\n\nIhr und Anduin könnt ruhig gegen mich antreten. Vielleicht habt Ihr ja zusammen eine Chance!\n\n<Faerin lacht.>", sourceObjective = "Nehmt die Schlossfigur, um mit Faerin und Anduin eine Runde Schachzug des Lichts zu spielen.", completion = "Ich hoffe, das hat Euch auch etwas entspannt, {name}. Mir war nicht klar, wie dringend wir alle eine Pause gebraucht haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[79173] = { id = 79173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte für die Anstrengungen", description = "Als der Schatten auf unsere Stadt fiel, wurden viele lebenswichtige Vorräte unter dem Deckmantel der Dunkelheit gestohlen.\n\nJetzt da das Licht zurückkehrt, können wir wiederaufbauen, aber zuerst müssen wir uns zurückholen, was wir verloren haben.\n\nDurchsucht die Gegend und bergt alle Vorräte, die von Nutzen sein können.", sourceObjective = "Bergt diverse gestohlene Gegenstände aus der Umgebung, um unsere Bedürfnisse zu erfüllen.", progress = "Habt Ihr die gestohlenen Gegenstände bergen können?", completion = "Ihr habt deutlich mehr wiedererlangt, als wir uns erhoffen konnten. Ich habe einige der überschüssigen Dinge beiseite gelegt, damit Ihr sie haben könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[79174] = { id = 79174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plagende Plagegeister", description = "Diese sporenverseucht'n Bestien beim Stütznest Vosh sind uns schon 'n Dorn im Auge, seit wir Faerins Vorstoß errichtet haben. Die verbreit'n dicke Sporenwolk'n. Sowas hab ich noch nie geseh'n.\n\nDie haben schon mal zugeschlag'n. Wird nich' lang dauern, bis sie's wieder tun. Wenn wir hier überleb'n woll'n, müss'n wir ihre Zahl verringern.\n\nGeht zu Stütznest Vosh und tötet 'n paar dieser sporenverseucht'n Bestien.", sourceObjective = "Tötet 12 sporenverseuchte Bestien bei Stütznest Vosh.", completion = "Jetzt, da die Zahl der sporenverseucht'n Bestien verringert wurde, haben wir genug Zeit, uns 'ne dauerhafte Lösung zu überleg'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[79175] = { id = 79175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich glaub, ich Spinne", description = "Da, ich habe etwas Kulanz bewiesen. Ihr habt einen kleinen Goblinfreund. Ich weiß ja, wie sehr Eure Art sich für jedes letzte bisschen Wärme aneinanderschmiegt.\n\nUnd jetzt erweist Ihr beiden mir ein paar Gefallen. Zunächst einmal gebe ich Euch meine Pheromongeruchsmarkierung. Das hält meine loyalen Soldaten davon ab, Euch anzugreifen. Sie markiert Euch als mein Eigentum.", sourceObjective = "Erlaubt Anub'azal, Euch mit seinen Pheromonen zu markieren.", progress = "Verschwendet nicht meine Zeit. Seid Ihr bereit, meine Markierung zu erhalten? Schreitet gemeinsam mit Eurem Goblinfreund in die Pheromonwolke und reibt Euch gut ein.", completion = "Euer Freund beschwert sich, aber durch meine Markierung seid Ihr vergleichsweise sicher, außer bei den Wachen von Zev'kall. Die kümmern sich nicht um Geruchsmarkierungen, wenn sie mir sowieso schon feindlich gesinnt sind.\n\nMacht also das Beste daraus, aber passt auf Euch auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[79176] = { id = 79176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Opale und Runen", description = "Ihr habt mir einen katastrophalen Tag erspart, {name}. \n\nDafür gebührt Euch der Dank der gesamten Schmiedegründe und derer, die sie am Laufen halten.\n\n<Vokgret zwinkert Euch zu und zeigt ein wissendes Lächeln.>\n\nEs war richtig von Bevrusi, Euch zu mir zu senden. Sagt ihr, dass sie keine Fremde mehr sein soll. Ich könnte mehr Freunde aus den Tiefen gebrauchen.\n\nHier ist ihr Flüssigopal. Gebt ihn ihr mit meinen besten Grüßen.", sourceObjective = "Tauscht den Flüssigopal gegen die Spelunkenpassrune von Bevrusi ein.", progress = "Jeder in der Stadt braucht etwas, und es gibt immer jemanden, der die Mittel hat, es zu besorgen.", completion = "Ich entsende Euch zu einem Maschinenflüsterer, um uns in die Spelunke zu bringen, und Ihr helft der Marktvögtin der Schmiedegründe bei einer krummen Liefer- und Handelsaktion?\n\n<Merrix grinst verschmitzt und klatscht mit seinen schweren Steinhänden Beifall. Der ist viel leiser, als Ihr gedacht hättet.>\n\nGut gemacht, mein einfallsreicher Fremdling.", sourceObjectiveStatus = "unverified-source-field" }
quests[79178] = { id = 79178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spielt Hearthstone!", description = "Zeit für eine Runde Hearthstone!\n\nHier ist ein Starterpaket. Macht es auf und erweitert Eure Sammlung um diese Karten. Wenn Ihr dann einen Platz am Spieltisch findet, könnt Ihr Euch zu jemandem setzen und spielen!\n\nWenn Ihr keinen Platz findet, möchtet Ihr vielleicht einige wilde Karten... Hier schleicht irgendwo ein zwielichtiger Kartenhändler herum, aber das wisst Ihr nicht von mir...", sourceObjective = "Spielt 5 Hearthstone-Karten an einem Hearthstone-Spieltisch aus oder wilde Karten IN DER NÄHE eines Hearthstone-Spieltisches.", progress = "Gefällt Euch das Spiel bisher? Wagt einen Versuch und spielt diese Karten!", completion = "Wie ist es Euch ergangen? Ihr hatte sicher jede Menge Spaß, ohne zu schummeln!", sourceObjectiveStatus = "unverified-source-field" }
quests[79184] = { id = 79184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir feiern das Hearthstone-Jubiläum!", description = "Hearthstone wird schon seit zehn Jahren gespielt, ist das zu glauben?\n\nIch veranstalte Hearthstone-Spiele in Valdrakken, oben am Sitz der Aspekte. Kommt vorbei!\n\n- Ferala, Zeremonienmeisterin", sourceObjective = "Sprecht mit Zeremonienmeisterin Ferala in Valdrakken am Sitz der Aspekte.", completion = "Willkommen bei den Festivitäten! Und jetzt zieht los und habt Spaß!", sourceObjectiveStatus = "unverified-source-field" }
quests[79186] = { id = 79186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir feiern das Hearthstone-Jubiläum!", description = "Hearthstone wird schon seit zehn Jahren gespielt, ist das zu glauben?\n\nDie Zeremonienmeisterin Ferala veranstaltet Hearthstone-Spiele im Hafen von Sturmwind. Kommt vorbei!", sourceObjective = "Sprecht mit Zeremonienmeisterin Ferala in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[79189] = { id = 79189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir feiern das Hearthstone-Jubiläum!", description = "Hearthstone wird schon seit zehn Jahren gespielt, zehn Jahre, ist das zu glauben?\n\nDie Zeremonienmeisterin Ferala veranstaltet Hearthstone-Spiele in Durotar, zwischen Orgrimmar und den Docks. Kommt vorbei!", sourceObjective = "Sprecht mit Zeremonienmeisterin Ferala in Durotar.", sourceObjectiveStatus = "unverified-source-field" }
quests[79193] = { id = 79193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drehende Sporenstacheln", description = "Orsenth schickt Euch? Und wir sind angeblich Partner? Ach... ich trage ja ein Medaillon. Aber ich habe keine Erinnerungen... Nun, keine Zeit für sowas.\n\nHabt Ihr auf dem Weg hierher diese sich drehenden Sporen gesehen? Ich brauche ihre Stacheln für... Ich brauche sie für... Wofür noch gleich? Oh, ja! Es gibt kein besseres Werkzeug zum Gravieren der kleinen Details, die ich bei meiner Arbeit als Juwelenschleifer brauche. Werdet Ihr mir einige sammeln?\n\nIch mache mich auf den Weg zurück zur Raffinerie. Kann es kaum erwarten, diese Orsenth kennenzulernen.", sourceObjective = "Sammelt 150 Sporenstacheln für Munderut.", progress = "Sieh mal einer an, was ist denn das? Ihr kennt Euch nicht aus in diesen Tiefen, nicht wahr? Was tut Ihr hier?\n\n<Ihr erinnert ihn an alles, worüber ihr gesprochen habt.>\n\nNun, worauf wartet Ihr? Geht und besorgt mir diese Stacheln!", completion = "Wo seid Ihr hergekommen? Wer seid Ihr?\n\nIch weiß nicht, woher Ihr wusstet, dass ich diese Stacheln brauche, aber ich danke Euch. Es gibt kein besseres Werkzeug zum Gravieren der kleinen Details, die ich bei meiner Arbeit als Juwelenschleifer brauche. Ich bin ein Juwelenschleifer, müsst Ihr wissen!\n\nHabt Ihr meine neue Freundin Orsenth gesehen? Was... Wovon habe ich gerade gesprochen?", sourceObjectiveStatus = "unverified-source-field" }
quests[79194] = { id = 79194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Quelle", description = "Orsenth hat mir berichtet, dass Ihr für die Lösung des Elementarproblems hier in der Mine entscheidend wart. Ich bin Keldaz, Aufseherin der Miliz. Wir kamen, sobald die Nachricht über den Angriff uns in Gundargaz erreichte. Die geretteten Minenarbeiter sagten, dass die Elementare aus dem nordöstlichen Minenschacht strömten.\n\nIch werde einige meiner Wachen zur Unterstützung hier stationieren und habe nach Verstärkung geschickt. Trefft mich vor der Höhle, wenn Ihr weiter helfen wollt, dann sehen wir, wie wir den Strom der Elementare aufhalten können.", sourceObjective = "Trefft Keldaz vor der nordöstlichen Mine.", completion = "Ah, {name}, Ihr habt es geschafft. Wir ebenso, aber wir wurden unterwegs angegriffen. Leider hat Nanthaz einen schweren Schlag einstecken müssen und muss sich erholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79196] = { id = 79196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angesehen bei den Durchtrennten Fäden", description = "Die Weberin behält Euch stets im Auge und hat entschieden, dass Ihr von größerem Nutzen seid, wenn Ihr mehr Ressourcen zu Verfügung habt.\n\nKommt zum Nest der Weberin. Dort wartet ein Paket auf Euch.", sourceObjective = "Sprecht mit Lady Vinazian im Nest der Weberin.", completion = "Für Eure bereits erbrachten und in Zukunft noch zu erbringenden Dienste nehmt das hier mit den besten Grüßen der Weberin entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79197] = { id = 79197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oberflächengebunden", description = "{name}, der Augenblick ist gekommen. Wir müssen uns schnell in die Stadt Dornogal begeben, wo unsere Verbündeten warten.\n\nNur gemeinsam haben wir eine Chance gegen die Machenschaften der Vorbotin.", sourceObjective = "Trefft Euch mit Moira Thaurissan und Euren Verbündeten in Dornogal auf der Insel von Dorn.", completion = "Schön, dass Ihr alle unbeschadet wieder zurück seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[79199] = { id = 79199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angesehen bei Fasshaxes Besatzung", description = "Eure Taten sind nicht unbemerkt geblieben. Ihr stellt immer wieder unter Beweis, dass Ihr <ein berühmter Forscher/eine berühmte Forscherin> seid!\n\nKehrt ins Drachenschuppenbasislager zurück. Ich habe einige Vorräte vorbereitet, die Euch in Euren Anstrengungen unterstützen sollen.", sourceObjective = "Sprecht mit Katalogisiererin Jakes im Drachenschuppenbasislager.", sourceObjectiveStatus = "unverified-source-field" }
quests[79200] = { id = 79200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer bin ich?", description = "Schön zu sehen, dass Ihr wach seid. Ihr müsst so viele Fragen haben, und wir werden sie Euch beantworten. Ich bin Aurora und das ist Vorarbeiter Uzjax.\n\nVieles hat sich verändert, seit Ihr zuletzt eingeschlafen seid, auch das Erweckungsprotokoll. Wir beide sind hier, um Euch beizustehen.\n\nWie in vielen anderen frisch Erweckten summt ein fernes, aber mächtiges Lied in Euch. Eine strahlende Welle der Veränderung.\n\nUmarmt sie.", sourceObjective = "Schließt den ersten Schritt des Erweckungsprotokolls ab.", completion = "Ich versichere Euch, dass Ihr nicht beschädigt seid.\n\nDieses Protokoll wurde entworfen, um 'Anomalien' in Irdenen festzustellen. Anomalien wie dieses Gefühl, das Euch überkam.\n\nDoch es handelt sich dabei nicht um Anomalien. Nicht mehr.\n\n<Aurora schenkt Euch ein beruhigendes Lächeln.>", sourceObjectiveStatus = "unverified-source-field" }
quests[79201] = { id = 79201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Analyseschnittstelle", description = "Das ist die Analyseschnittstelle.\n\nUm sicherzustellen, dass unsere Hauptprogrammierung intakt bleibt, wurden diese Konsolen installiert. Sie führen eine Reihe an Untersuchungen durch, um die Erinnerungsmatrizen frisch erweckter Irdener zu prüfen.\n\nAuch wenn Aurora Euch dazu ermutigen wird, so zu antworten, wie es Euch beliebt... Ich... Na ja, ich hoffe einfach, dass Ihr wahrheitsgemäß antwortet.\n\nFahrt fort, sobald Ihr bereit seid.", sourceObjective = "Schließt die Analysesequenz an der Analyseschnittstelle ab.", completion = "Wer war ich, wer bin ich und wer will ich sein?\n\nDas sind alles Fragen, die jeder Irdene ab sofort stellen darf.\n\nEs ist an uns, unser Schicksal und unseren Sinn im Leben zu wählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79202] = { id = 79202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stein auf Stein", description = "Willkommen im Prozeduralen Forum.\n\nVorarbeiter Uzjax hat mir gesagt, dass diese Kammer früher als unsere Testeinrichtung für Aufgaben diente.\n\nUnter seiner Anleitung haben wir diese Kammer umfunktioniert.\n\nIrdene sind nicht von Natur aus kampferprobt, deshalb dient dieser Raum nun dazu, neu erweckte Irdene auf die Herausforderungen der unerforschten Welt vorzubereiten, die vor ihnen liegt.", sourceObjective = "Tragt Übungskämpfe gegen 6 frisch erweckte Irdene aus.", progress = "Egal, ob sie einst Sturmreiter, Friedensbewahrer, Handwerker oder Arbeiter waren, es braucht Zeit, die eigenen Fertigkeiten im Kampf zu verbessern.", completion = "Der Kampf liegt den meisten Irdenen nicht, und doch übertrefft Ihr unsere Erwartungen.\n\nEuer Training kommt zu einem außerordentlich passenden Zeitpunkt. Vor uns scheint ein unerwartetes Hindernis zu liegen.\n\nSprecher Kuldas kann Euch alles Weitere erklären.", sourceObjectiveStatus = "unverified-source-field" }
quests[79203] = { id = 79203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Autorisierung: Abgelehnt", description = "Das Bollwerk der Autorisierung! So hieß dieser Raum einst.\n\nIch habe unermüdlich daran gearbeitet, ihn in seinen Ursprungszustand zurückzuversetzen, als plötzlich der ganze verdammte Raum bebte. \n\nEin Golem erschien aus dem Nichts und griff meine Maschinisten an! Wir konnten entkommen, aber der Golem hat die Türen geschlossen.\n\nAurora glaubt offenbar, dass Ihr Euch darum kümmern könnt. Seid ihr bereit?", sourceObjective = "Besiegt den Phalanx der Autorisierung im Bollwerk der Autorisierung.", completion = "Ich hab öfter, als mir lieb ist, gesehen, wie der Raum zum Leben erwacht, {name}. Aber das war eine ganz wilde Sache! \n\nIch frage mich wirklich, woher der Golem kam. Irden war er auf jeden Fall nicht.\n\nKaum dachte ich, ich weiß alles über diesen Ort, wirft er mir wieder einen Stab ins Getriebe.\n\nNa ja, zurück an die Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[79204] = { id = 79204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer auch immer Ihr sein wollt", description = "Nach einem solchen Erweckungsprotokoll kann ich verstehen, warum Aurora sagt, dass Ihr etwas Besonderes seid.\n\nDie Welt ist nicht auf einen Irdenen wie Euch vorbereitet. \n\n<Kuldas klopft Euch mit einem gewichtigen Kichern auf die Schulter.>\n\nAurora und der Vorarbeiter warten in der Vorhalle des Erwachens auf Euch.\n\nNun geht schon! \n\nSchließt Euer Erweckungsprotokoll ab und verschwindet von hier!", sourceObjective = "Sprecht mit Aurora, um Euer Erweckungsprotokoll abzuschließen.", completion = "Nach Abschluss ihres Erweckungsprotokolls verlassen Irdene diese Hallen und begeben sich zu den ihnen zugewiesenen Zuständigkeitsbereichen in den Schallenden Tiefen.\n\nIhr Zweck wurde für sie bestimmt. Doch diese Zeiten sind vorbei.\n\nÜber das Schicksal unseres Volkes entscheiden nun ganz allein wir selbst.\n\nWas Ihr tut und wohin Ihr geht, liegt ganz bei Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[79205] = { id = 79205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hier wird nichts verschwendet", description = "Alles seinen Zweck haben, ich sagen. Selbst Dinge, die Steinköpfe wegwerfen und für wertlos halten.\n\nKobolde besser wissen.\n\nGeht nun und seht, was Ihr finden. Müssen viel Schrott wiederverwerten. Genug, damit Kobold neues Zuhause bauen!", sourceObjective = "Sammelt potenziell verwertbaren Schrott im gesamten Hasenbau.", progress = "Ihr nachher überrascht sein. Koboldhandwerk sehr gut!", completion = "Nicht schlecht für jemanden von Eurem Volk. Wir das gut verwenden werden.\n\nZumindest das meiste. Manchmal Müll von anderen einfach nur Müll.", sourceObjectiveStatus = "unverified-source-field" }
quests[79206] = { id = 79206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschädigte Erinnerungen", description = "Irgendetwas an diesem besonderen Edelstein scheint wichtig zu sein. Es könnte sich lohnen, ihn zu Sprecherin Brinthe zu bringen.", sourceObjective = "Bringt den verblassten Erinnerungsedelstein zu Brinthe.\n\nBereitgestellter Gegenstand:", completion = "Irdene verwenden diese Edelsteine, um Erinnerungen aufzubewahren, die wir andernfalls an den unablässigen Strom der Zeit verlieren würden.\n\nWenn ein Irdener in Stasis übergeht, verwenden wir manchmal einen Erinnerungsedelstein, um seine letzten Momente zu sehen.\n\nSolange wir leben, nutzen wir die Edelsteine dafür, um unsere kostbaren Erinnerungen ins Archiv zu bringen, wo sie aufbewahrt werden können. Dann laden wir unseren Körper wieder auf und erneuern unseren Geist in der Erweckungsmaschine.\n\nDanke, dass Ihr dies zurückgebracht habt, {name}. Selbst in diesem zerschmetterten und verblassten Zustand ist es noch sehr wertvoll.", sourceObjectiveStatus = "unverified-source-field" }
quests[79213] = { id = 79213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Anachronismus", description = "Legt die Batterien in die zylindrischen Vertiefungen in der Konsole.\n\nDann, so die Titanen wollen, sehen wir, was drauf ist.", sourceObjective = "Aktiviert die ausgegrabene Konsole und nutzt das Gerät, um die Sargassumwache auf Golgrins Insel zu besiegen.", progress = "Findet einen ausreichend großen Elementar, um das Artefakt mit der notwendigen Energiemenge aufzuladen.\n\nWenn ich recht habe, sollte das Titanenartefakt den Rest erledigen.", completion = "Sonderbar. Es stößt ein Signal aus, das mir bekannt vorkommt.\n\nIch habe eine Ahnung, wo es uns hinführen könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[79216] = { id = 79216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Netz der Manipulation", description = "Diese Stadt wurde belagert und von Spinnen überrannt! Selbst wenn wir sie beseitigen, kommen sie immer wieder zurück.\n\nIrgendetwas steckt hinter diesen Angriffen!\n\nEin kleiner Felsvorsprung nordöstlich der Blüte des Lichts ist der Unterschlupf dieser Spinnen. Erkundet diesen Felsvorsprung. Findet heraus, was diese Spinnen dazu bringt, uns anzugreifen, und bereitet dem ein Ende!", sourceObjective = "Erforscht den Sims in der Nähe und kümmert Euch um alle Bedrohungen dort.", progress = "Habt Ihr unser Spinnenproblem lösen können?", completion = "Ausgezeichnete Arbeit, {name}. Jetzt wollen wir mal sehen, ob das dieser achtbeinigen Invasion einen Riegel vorschiebt!", sourceObjectiveStatus = "unverified-source-field" }
quests[79217] = { id = 79217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zur Basis", description = "Es wird eine Herausforderung, diese Fabrik wieder in Betrieb zu nehmen, aber ich glaube, wir werden uns da was einfallen lassen. Kehren wir nach Gundargaz zurück und beraten wir uns mit einem Freund.\n\nSein Wissen wird uns hier von großem Nutzen sein.", sourceObjective = "Trefft Euch mit Brinthe in Gundargaz.", completion = "Seid Ihr bereit, die Köpfe zusammenzustecken und einen Plan zu entwickeln?", sourceObjectiveStatus = "unverified-source-field" }
quests[79218] = { id = 79218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angesehen bei den Arathi von Heilsturz", description = "Eure Anstrengungen für das Wohl unseres Volks sind uns nicht entgangen. Und sie werden auch belohnt werden.\n\nIhr findet mich in Mereldar.", sourceObjective = "Sprecht mit Auralia Stahlstoß in Mereldar.", completion = "Uns gehen die Vorräte aus, doch in Euren Händen werden diese Güter allen Algari zugutekommen. Möge die Heilige Flamme Euch den Weg leuchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[79219] = { id = 79219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhmreich beim Rat von Dornogal", description = "Der Rat steht weiterhin in Eurer Schuld.\n\nWenn Ihr mich in Dornogal besucht, werde ich Euch Vorräte geben, um damit zu beginnen, diese Schuld zu begleichen.", sourceObjective = "Sprecht mit Auditor Balwurz in Dornogal.", completion = "Belohnungen werden ausgegeben. Habt Dank, Champion. Dies sollte eine angemessene Belohnung für Eure Bemühungen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[79220] = { id = 79220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angesehen beim Konvent der Tiefen", description = "Gute Arbeit verdient eine gute Belohnung, nicht wahr?\n\nMontage ist dankbar. Wachshändler Squick ist dankbar. Zeigen Dankbarkeit mit vielen Vorräten.\n\nKommt zu Wachshändler Squick in Gundargaz.", sourceObjective = "Sprecht mit Wachshändler Squick in Gundargaz.", completion = "Für Euch! Nehmt!", sourceObjectiveStatus = "unverified-source-field" }
quests[79221] = { id = 79221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ungewöhnliches Tierchen", description = "Neruber in Rak-Ush könnten sich für diese seltsame kleine Spinne interessieren.", sourceObjective = "Bringt dieses ungewöhnliche Tierchen zu Witwe Arak'nai in Rak-Ush.\n\nBereitgestellter Gegenstand:", completion = "Oh, ich hatte mich schon gefragt, wohin die verschwunden waren, danke fürs Zurückbringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[79222] = { id = 79222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattengehärtete Triebfeder", description = "<Vielleicht waren es die Auswirkungen der anhaltenden Dunkelheit oder die Tüfteleien von Ezgi Eisenzeug, aber die Kraft dieser Feder könnte Sprecher Kuldas in Gundargaz interessieren.>", sourceObjective = "Bringt diesen Gegenstand zu Kuldas in Gundargaz.\n\nBereitgestellter Gegenstand:", completion = "Ein wahrlich exzellenter Fund, ich werde ihn gründlichst untersuchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[79223] = { id = 79223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endlich <Archivar/Archivarin>!", description = "Ihr habt Euch also eingearbeitet? Ihr habt Euch die Hände schmutzig gemacht? Ihr habt die Geschichte gekostet?\n\nWarum feiern wir diesen glorreichen Moment des überdurchschnittlichen Erfolgs nicht mit... einer Kappe?!\n\nGanz richtig! Nehmt dieses Geschenk unserer geschätzten Versorgerin Aristta. Sie wird Euch gerne eine unserer Allzweckkappen überreichen, damit jeder Eure Beförderung <zum Archivar/zur Archivarin> sofort sehen kann.", sourceObjective = "Kauft eine Schnallenkappe des Archivars von Versorgerin Aristta.", progress = "Die Kappe steht Euch gut!", completion = "Ungeachtet irgendwelcher Einschätzungen Eurer aktuellen Eignung kann man sagen, dass Ihr zumindest ausseht wie ein Archivar!\n\nNa dann, meine Kollegen verlangen wieder nach Euren Talenten. Trödelt nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[79224] = { id = 79224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Informationsbeschaffung", description = "Witwe Arak'nai ließ uns eine Nachricht mittels einer ihrer sogenannten \"Weberatten\" zukommen. Sie hat eine Spur, die für unsere Sache von Bedeutung sein könnte, und möchte, dass wir dieser Spur nachgehen. Alles Training der Welt ist nutzlos, wenn wir unseren Feind nicht kennen.\n\nMeine eigenen Aufklärungsbemühungen in Azj-Kahet waren... nur teilweise erfolgreich, wie Ihr vielleicht noch wisst. Ich gebe zu, dass ich nicht allzu erpicht bin, alsbald dorthin zurückzukehren. Glücklicherweise ist Verstärkung eingetroffen, darunter eine Meisterspionin.\n\nDoch leider ist sie... nun, Ihr werdet schon sehen.", sourceObjective = "Sprecht mit Witwe Arak'nai im Nest der Weberin in Azj-Kahet.", completion = "Wie ich Eurer mürrischen kleinen Meisterspionin gerade sagen wollte, erwarte ich, dass das ein Unterfangen wird, das für beide Seiten von Vorteil ist.\n\nWenn wir fertig sind, haben wir beide die Informationen, die wir brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79225] = { id = 79225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorene Flamme", description = "<Ein Zunderkasten eines Mitglieds der Heilsturzexpedition, ihn zurückzubringen, würde die Erinnerung an all jene ehren, die mutig ihr Leben gaben.>\n\nEine Expeditionsspäherin könnte mehr über diesen Gegenstand wissen.>", sourceObjective = "Bringt den Expeditionszunderkasten zu Keyrra Flammenzunge beim Schattenhainweingut.\n\nBereitgestellter Gegenstand:", completion = "Am Tag der Schatten geriet Augustin in Panik und verließ seine Stellung.\n\nEs gab Gerüchte, dass er Heilsturz verlassen und einen Weg an die Oberfläche gefunden hatte. Offenbar gelang es ihm nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[79226] = { id = 79226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das große Buddeln: Ruhestätte des Verräters", description = "Setzt Eure Kappe auf, schlüpft in ein Paar robuste Handschuhe und bringt etwas zum Naschen mit, denn die Ruhestätte des Verräters ist bereit für Archivare, die sich die Hände schmutzig machen wollen!", sourceObjective = "Helft Eadweard Dalyngrigge und den Archivaren von Azeroth beim großen Buddeln bei der Ruhestätte des Verräters.", progress = "Man gräbt nicht jeden Tag antike Drachengeheimnisse aus... oder einen ganzen Drachen!", completion = "<Eadweard durchsucht die zahllosen Taschen seiner Robe.>\n\nHier, Archivar {name}! Bringt das für Eure Belohnung zu Versorgerin Aristta.\n\nIch würde Euch auch zu einer neuen Montur raten. Eure aktuelle ist... recht fleckig.", sourceObjectiveStatus = "unverified-source-field" }
quests[79227] = { id = 79227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus der Spinnenperspektive", description = "Ich habe selbstverständlich in jeder Ecke der Stadt meine Augen... mit Ausnahme von einer.\n\nDas Transformatorium ist das Gelände für Ansureks frühreifste Lakaien und höchstgeschätzte Haustiere. Das ist der Ort, an dem der Aufstiegsprozess entwickelt wurde. Ich habe ihn erst vor Kurzem zwischen die Krallen bekommen, und auch nur dank unserer werten Y'tekhi hier. Aber vieles davon ist mir nach wie vor unbehaglich schleierhaft.\n\nIch glaube, es ist an der Zeit, Bein anzulegen. Platziert Schattenwerfer, um Informationen von meinen Spähern zu erhalten. Trefft anschließend Y'tekhi und Eure eigene Meisterspionin Voss in einer diskreten Ecke des Bezirks.", sourceObjective = "Platziert Schattenwerfer, um Euch mit den Spähern der Weberin im Umbralbasar, der Östlichen Spanne und der Zuckenden Schlucht zu treffen.", completion = "Diese Berichte gefallen mir gar nicht. Was auch immer sie vorhaben, scheint sich zuzuspitzen. Und zwar genau zur rechten Zeit, dass wir dazwischengeraten.\n\nKeine Sorge, ich lasse Euch wissen, wenn wir zu tief hineingeraten.", sourceObjectiveStatus = "unverified-source-field" }
quests[79230] = { id = 79230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das leise Krabbeln", description = "Ich habe drei interessante Orte ausgemacht.\n\nEin Lager auf der Ostseite der Anlage, ein Lagerhaus in der Mitte und diese große Speichereinheit mit den königlichen Flaggen der Sureki daran. Dort treffen wir uns.\n\nWir werden uns getrennt voneinander durch das Gelände bewegen. Das sollte die Chancen verringern, entdeckt zu werden. Ihr mögt vor den meisten Nerubern verborgen sein, doch die Aufgestiegenen werden Euch herausriechen können. Werft ihnen einige dieser Zornespheromone entgegen, wenn es brenzlig wird, das sollte sie ablenken.\n\nBleibt wachsam, bleibt leise.", sourceObjective = "Untersucht die westliche Vorräte, das zentrale Lagerhaus und den königlichen Speicher des Transformatoriums und verwendet Zornespheromone, um Wachen abzulenken und nicht aufzufliegen.", progress = "Werdet nicht unachtsam. Nicht hier.", completion = "Wir sind hier runtergekommen, um herauszufinden, was diese Neruber vorhaben. Ich glaube nicht, dass mir die Antwort gefällt.", sourceObjectiveStatus = "unverified-source-field" }
quests[79231] = { id = 79231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück ins Hauptquartier! Erneut!", description = "Ihr habt großartige Arbeit geleistet! Es besteht kein Zweifel: Ihr seid in der Tat <ein echter Archivar/eine echte Archivarin> von Azeroth.\n\nTrefft uns in unserem Hauptquartier in Thaldraszus. Eadweard möchte all Eure wertvolle Arbeit und Erfolge für unsere Gruppe festhalten.", sourceObjective = "Trefft Euch mit Eadweard Dalyngrigge in der Akademie von Algeth'ar in Thaldraszus.", completion = "Ausgezeichnete Arbeit, {name}! Wirklich ausgezeichnete Arbeit!\n\nIch sehe, dass ich richtig lag, Euch herzuholen. Ihr besitzt wahrhaft den Geist eines Archivars!", sourceObjectiveStatus = "unverified-source-field" }
quests[79232] = { id = 79232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jene, die fielen", description = "Seit dem Tag der Schatten waren diese Ländereien ein gefährlicher Ort. \n\nDie Kobyss sind ermutigt, die Neruber tasten sich in unserem Land vor und Kreaturen des reinen Schattens fangen an, sich zu manifestieren.\n\nDie Erinnerung an die Gefallenen ist in unseren Alltag eingebrannt. Wir müssen ihre Überreste finden, um Frieden zu erlangen. \n\nSucht die Zunderkästen dieser vermissten Expeditionsmitglieder und bringt sie zu mir.", sourceObjective = "Macht die sterblichen Überreste von Oskaer Talkampf, Dalian Eisenbinder und Idona Seherstein ausfindig und bergt ihre Zunderkästen.", progress = "Habt Ihr die Zunderkästen gefunden?", completion = "Diese Zunderkästen sind nur ein kleines Symbol für die schrecklichen Verluste, die wir am Tag der Schatten erlitten. Wir werden die Überreste bergen, die Ihr aufgespürt habt, damit wir die Erinnerungen an unsere geliebten Brüder und Schwestern heilen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[79233] = { id = 79233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Laborzugang", description = "So sehr ich es auch liebe, in den Schatten zu lauern, die wirklich pikanten Informationen werden sich im Laboratorium der großen Verbinderin selbst befinden.\n\nSelbstverständlich braucht Ihr da drin die richtigen Pheromone, doch das ist nichts, was mit etwas biologischer Fälscherei nicht zu schaffen ist.\n\nDie nerubischen Loyalisten hier stehen mit Sicherheit auf der Gästeliste. Sechs Einheiten ihrer Absonderungen sollten genug sein, um uns drei zu maskieren.", sourceObjective = "Sammelt 6 Absonderungen der Loyalisten von nerubischen Loyalisten im Bereich des Transformatoriums.", progress = "Ob Ihr mich gesehen habt? Nein, habt Ihr nicht.", completion = "Endlich! Ich hatte mich schon gefragt, wann wir endlich über die echte Intrige stolpern.", sourceObjectiveStatus = "unverified-source-field" }
quests[79234] = { id = 79234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleiner Beutel mit Samen", description = "<Dieser kleiner Beutel mit Samen scheint vergessen, vielleicht kann Aliya Hügelpinne etwas damit anfangen.>", sourceObjective = "Bringt diesen kleinen Beutel mit Samen zu Aliya Hügelpinne auf dem Hügelpinnenhof.\n\nBereitgestellter Gegenstand:", completion = "Oh, vielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[79237] = { id = 79237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erschaffung eines Monsters", description = "Wir haben ein neues Ziel: herauszufinden, was Ansureks Pläne für dieses... Ding sind.\n\nWir werden die Antworten im Laboratorium der großen Verbinderin selbst finden. Da würde ich meine Klingen drauf verwetten.\n\nIch habe auf dem Dach einen Luftschacht entdeckt, den Ihr mit Eurem Greifhaken erreichen könnt. Y'tekhi hat ein seltsames Gemisch zusammengebraut, das uns drinnen angeblich die nötige Freigabe verschaffen kann. Bäh.\n\nWir treffen uns dort.", sourceObjective = "Betretet das Laboratorium der großen Verbinderin über den Luftschacht und geht anschließend Hinweisen darüber nach, was der Zweck der ersten Aufgestiegenen ist.", progress = "Das gefällt mir nicht. Es gibt hier immer noch etwas, das sich uns entzieht.", completion = "Das... hatte ich nicht erwartet, herauszufinden.\n\n<Lilian räuspert sich.>\n\nFamiliendrama beiseite, was auch immer die alte Königin einmal war, sie wird sich zu einem großen Problem für uns entwickeln, wenn sie unweigerlich auf dem Schlachtfeld erscheint.", sourceObjectiveStatus = "unverified-source-field" }
quests[79239] = { id = 79239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Königin in Ketten", description = "Ansurek... diese Made. Diese einfältige, feige kleine...\n\n<Y'tekhi knurrt leise und ringt darum, nicht die Fassung zu verlieren.>\n\nWenn das hier ist, was aus Neferess geworden ist, dann müssen wir sie befreien. Sie ist nach wie vor unsere Königin. Meine Gebieterin wird wissen, was zu tun ist.\n\nWenn die Weberin erfährt, was sie alle getan haben, wird es keinen Spalt geben, der tief genug ist, um ihrem Zorn zu entkommen.", sourceObjective = "Zerstört die Fesseln von Neferess.", completion = "Sagte ich nicht, dass ich Euch wissen lassen würde, wenn wir zu tief hineingeraten? Den Punkt haben wir jetzt erreicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[79240] = { id = 79240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agentin wider Willen", description = "Wir haben Y'tekhi verloren.\n\nWir können uns später über das Wie Gedanken machen. Macht Euch jetzt erst mal Sorgen darum, sie auszuschalten, bevor es noch schlimmer wird.\n\n<Lilian schnaubt.>\n\nIch schätze mal, dass wir hier runtergekommen sind, um herauszufinden, was Xal'atath auf Lager hat. Ich wünschte, wir hätten uns um unseren eigenen Kram gekümmert.", sourceObjective = "Überwältigt Y'tekhi.", progress = "Schwer zu sagen, ob das noch schlechter hätte ausgehen können.", completion = "Wir stehen nicht mehr im Rampenlicht. Vorerst.\n\nEs ist meine Priorität, Y'tekhi zurück zur Weberin zu bringen. Eure Priorität ist, Euch um die Waffen zu kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[79241] = { id = 79241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Laut und deutlich", description = "Das mit dem unbemerkt bleiben können wir jetzt wohl vergessen. Wenigstens können wir nun, da unsere Deckung aufgeflogen ist, hier richtig Radau machen.\n\nWir wissen, dass sie Waffen über die südliche Brücke transportieren. Wenn wir diese Waffen gegen sie selbst richten, müssen sie ihre komplette Armee neu versorgen. Das wird uns wenigstens etwas Zeit verschaffen.\n\nIch habe sechs Schwachstellen beim Konvoi ausgemacht. Bringt an allen Bomben an, macht Euch anschließend aus dem Staub und genießt das Feuerwerk.", sourceObjective = "Bringt 6 konfiszierte nerubische Ladungen am Konvoi an und zündet sie dann aus der Ferne.", progress = "Sie wissen, dass wir hier sind, dann können wir auch gleich das Beste daraus machen.", completion = "Der Konvoi liegt nicht nur in Trümmern, wir konnten das Chaos sogar nutzen, um uns davonzustehlen. Wenn Ihr etwas könnt, dann Lärm machen.\n\nLeise bleiben? Ach, da können wir noch dran arbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[79243] = { id = 79243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Selbstgemachte Meuterei", description = "Uns fehlt die Feuerkraft, um ihre gesamte Produktion auseinanderzunehmen. Wir haben allerdings noch zwei Phiolen mit Zornespheromonen übrig. Holen wir das Optimum aus ihnen raus.\n\nEin Belagerungsmarschall und ein Rüstmeister beaufsichtigen die Vorbereitungen und geben Befehle aus. Eigentlich Logistikexperten, aber trotzdem recht schlagkräftig... und genau da kommen die Pheromone ins Spiel.\n\nTrefft sie mit einer Phiole, dann wird sich ihre eigene Armee gegen sie wenden. Wenn wir beide ausschalten, legen wir ihr Unterfangen lahm.", sourceObjective = "Tötet Belagerungsmarschall Tekhzok und den königlichen Rüstmeister Ze'erik.", completion = "Es ist nur eine Verzögerung, kein voller Stopp, aber dennoch nicht zu unterschätzen. Das verschafft den Leuten oben mehr Zeit, Vorkehrungen zu treffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79244] = { id = 79244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neues aus dem Untergrund", description = "Die Explosionen konnte ich bis hierher hören. Das sollte uns etwas Zeit verschaffen. Ich wäre vermutlich auch erleichtert, wenn das weniger dürftig verlaufen wäre.\n\nY'tekhi ist hinten außer Hörweite sicher untergebracht. Was auch immer Xal'atath getan hat... es ist noch nicht abgeklungen. Die Weberin hat bereits Leute damit beauftragt, die Sache unter die Lupe zu nehmen, aber bisher sieht es nicht gut aus.\n\nAlleria wird einen Lagebericht wollen. Viel Glück.", sourceObjective = "Informiert Witwe Arak'nai darüber, was im Transformatorium gefunden wurde. Kehrt dann zu Alleria in Dornogal auf der Insel von Dorn zurück.", completion = "Am Ende des Tages haben wir ihren Vormarsch verzögert und einige gute, verwertbare Informationen gesammelt, mit denen die Leute oben arbeiten können.\n\nWar es das wert? Nun, das wird die Zeit zeigen.", sourceObjectiveStatus = "unverified-source-field" }
